"use strict";

const DESIGN_LIBRARY = (() => {
  const ml = [
    {
      id: "video-ranking", title: "Design a video ranking system",
      summary: "Retrieve broadly, rank for satisfying viewing, and prevent feedback loops.",
      flow: [["Events", "Impressions, playback, explicit feedback"], ["Candidates", "Subscriptions + ANN + fresh content"], ["Ranker", "Watch quality, satisfaction, risk"], ["Re-rank", "Diversity, freshness, eligibility"], ["Serve", "Cursor + exposure log"]],
      feedback: "Exposure and delayed satisfaction labels feed point-in-time training snapshots, not the live request.",
      scope: [
        "Clarify short-form versus long-form video, home feed versus related videos, logged-in users, and whether playback delivery is in scope. Design the home ranking API; a CDN serves video bytes separately.",
        "Optimize satisfying sessions and long-term retention, not raw watch time alone. Treat policy eligibility, age restrictions, creator diversity, and negative feedback as constraints rather than optional ranking features."
      ],
      capacity: ["Assume 10 million daily users, 20 feed requests/user/day: 200 million/day, about 2,315 average requests/s and 23,150/s at a 10x peak.", "Assume a 200 ms p95 ranking budget: 40 ms retrieval, 20 ms feature reads, 90 ms scoring, 20 ms re-ranking, 30 ms headroom. These are illustrative allocations; measure the end-to-end tail."],
      data: [
        "Log request_id, impression_id, user_id, video_id, position, eligibility decisions, model version, and playback outcomes. An impression is a shown item, not every item retrieved. Join delayed likes, skips, hides, and surveys back to impressions.",
        "Create watch-fraction and satisfied-view labels, with duration-aware treatment so long videos do not win mechanically. Exclude impossible playback telemetry and separate accidental starts. Split chronologically, group users where needed, and compute historical features as of impression time.",
        "Use content/audio/text embeddings, creator relationships, topic affinity, session history, and item freshness. Do not treat unexposed videos as observed dislikes. Position bias and exposure selection require randomized evaluation traffic or carefully justified propensity correction."
      ],
      model: ["Start with an eligibility-filtered popularity/recency feed plus subscription candidates. Add two-tower approximate-nearest-neighbor retrieval and a multi-task ranker predicting satisfied watch, skip, like, and hide.", "Use a bounded utility such as predicted satisfying seconds minus skip/hide penalties, with weights selected by product experiments. Train retrieval on observed positives with sampled negatives; account for sampling when interpreting predicted probabilities. Reserve small, safe exploration traffic for new items."],
      online: ["GET /feed?cursor=... uses authenticated user context and an opaque snapshot cursor. Merge candidates from several channels, remove blocked/ineligible/seen items, batch-fetch versioned features, score hundreds rather than the whole catalog, then apply slate diversity.", "Log the final displayed slate and scores asynchronously with durable buffering. Cache user/session embeddings, precompute item embeddings, and time-bound feature RPCs. Keep a safe popularity fallback when retrieval or ranking exceeds its deadline."],
      metrics: ["Measure Recall@K for candidate retrieval and NDCG@K with a stated relevance label for ranking. Compute calibration for predicted probabilities, then slice by new users, new creators, language, network quality, and video duration.", "For one positive among 20 eligible candidates, a retriever returning 10 items that include it has Recall@10 = 1 for that request; this says nothing about whether ranking placed it first. Report retrieval and ranking metrics separately.", "Run user-level A/B tests for satisfied sessions, retention, hides, policy exposure per 1,000 impressions, latency, and creator concentration. Predeclare guardrails and monitor novelty effects; avoid evaluating a user across both arms."],
      risks: ["A hot video can overload feature keys; shard/cache immutable item features and cap candidate-channel contributions. Detect stale embeddings, missing features, request timeouts, feedback-event lag, and training/serving feature mismatches.", "Do not let popularity monopolize exposure. Maintain exploration, frequency caps, diversity checks, and policy rechecks at serving time. Deletion or restriction must invalidate cached eligibility, not wait for the next model training."],
      tradeoffs: ["ANN retrieval reduces cost but can lose relevant candidates; measure channel coverage before spending on a larger ranker. More context improves personalization but increases tail latency and privacy surface.", "Ship baseline -> shadow scoring -> small randomized canary -> gradual ramp. Roll back model, feature schema, and embedding-index version together; do not silently substitute incompatible vectors."],
      followups: [["How do you rank a new video?", "Use content embeddings and creator/topic priors, then allocate bounded exploration. Evaluate discovery quality separately from established-item accuracy."], ["What if watch time rises but retention falls?", "Investigate clickbait, session fatigue, and cohort effects. Revisit utility and guardrails rather than declaring the watch-time lift a success."], ["How do you handle repeated requests?", "Use a session exposure history and snapshot cursor; keep pagination stable while refreshing candidate pools only at explicit boundaries."]]
    },
    {
      id: "place-recommendation", title: "Design a place recommendation system",
      summary: "Combine geographic feasibility, intent, business quality, and contextual personalization.",
      flow: [["Context", "Consent, location, time, intent"], ["Geo retrieval", "Nearby cells + category filters"], ["Eligibility", "Open, reachable, allowed"], ["Ranking", "Preference + travel cost + quality"], ["Map/list", "Diverse results + explanations"]],
      feedback: "Visits and reviews arrive late; aggregate them with consent and retain exposure context.",
      scope: ["Clarify restaurant discovery versus all places, map browsing versus a typed query, travel mode, and whether reservations are included. Ask whether the system should optimize a useful visit, a booking, or merely a click.", "Treat location as sensitive. Request permission, allow approximate or manually entered location, and provide non-personalized results if consent is absent."],
      capacity: ["Assume 2 million users x 5 searches/day = 10 million/day, about 116 average requests/s; size for a 20x meal-time peak of about 2,315/s.", "A 200 ms p95 response can retrieve coarse geographic cells first, then calculate expensive travel times only for a shortlist. Precompute common origin/destination travel estimates with freshness bounds."],
      data: ["Maintain place_id, coordinates, category, hours/time zone, price range, accessibility, freshness, and verified business status. Store source timestamps and confidence; an open-hours field can be wrong even if ranking is correct.", "Log impressions, query intent, location precision, selections, route starts, bookings, and confirmed visits where consent permits. A route start is a proxy, not proof of a successful visit. Filter review spam and deduplicate venues.", "Train with chronological snapshots and geography-aware holdouts. Test unseen neighborhoods and new places, not just random rows from familiar cities. Avoid using future reviews or later business closures in past features."],
      model: ["Begin with open/nearby/category matching plus quality and distance heuristics. Add semantic query/category retrieval and a ranker predicting useful selection or visit, using user cuisine/price preferences and current context.", "Model relevance and travel cost separately enough to explain trade-offs. A high-rated venue 90 minutes away is not automatically useful. Diversify categories and distance bands rather than returning near-duplicate branches."],
      online: ["GET /places?lat=...&lon=...&intent=... uses bounded location precision and authenticated preference access. Query a geo index such as hierarchical cells, expand neighboring cells, then apply exact-distance and eligibility checks.", "Batch-fetch venue features, estimate travel time for top candidates, rank and diversify. Include place_id, distance/travel estimate, freshness timestamp, and a concise explanation. Cache coarse anonymous popular results; do not share personalized cache entries between users."],
      metrics: ["Evaluate candidate recall within feasible travel constraints, NDCG@10 for intent relevance, closure-rate errors, and calibration for visit/booking probabilities.", "Online measure successful visit/booking rate, abandoned navigation, stale-hours complaints, geographic coverage, and latency. Use consented, delayed outcomes and show label maturity; clicks alone reward attractive but unsuitable venues.", "Slice by city density, rural areas, accessibility needs, cold users, and new venues. A/B by user; for local marketplace spillovers, discuss geographic cluster experiments and contamination."],
      risks: ["Stale hours or temporary closures invalidate recommendations; add fast business updates and serving-time checks. If map/travel providers fail, return labeled straight-line distance rather than misrepresenting it as travel time.", "Limit precise location retention, prevent sensitive-visit inference, and separate ad placements from organic relevance. Use fraud checks for review manipulation and appeals for business corrections."],
      tradeoffs: ["Strict radius filtering is fast but misses reachable venues across a radius boundary; retrieve broadly using cells and validate actual feasibility after. Travel-time ranking is more useful but expensive.", "Popularity helps cold start but entrenches established businesses. Use content/category priors, bounded exploration, and visibility reporting for new businesses."],
      followups: [["How do you serve a tourist?", "Use present intent, location, time, and explicit filters rather than inferring stable preferences from one trip."], ["What if GPS is inaccurate?", "Accept a precision radius, broaden retrieval, and ask for an area or map pin when precision materially changes results."], ["How do sponsored places fit?", "Use a separate eligible ad candidate path, clearly label sponsorship, and keep organic quality and advertising objectives distinguishable."]]
    },
    {
      id: "weapon-sale-detection", title: "Design a weapon sale detection system",
      summary: "Detect policy-violating sale offers while separating depiction, discussion, and legitimate context.",
      flow: [["Listing", "Text, images, policy jurisdiction"], ["Evidence", "OCR + object + contextual signals"], ["Risk model", "Sale intent + restricted category"], ["Decision", "Allow, review, or restrict"], ["Appeal", "Human audit + corrected labels"]],
      feedback: "Reviewed decisions and appeal outcomes improve labels; never expose detection loopholes or private enforcement signals.",
      scope: ["Frame this as marketplace safety and policy enforcement, not a way to facilitate sales. Define the platform policy, covered items, applicable jurisdictions, and actions available. A picture of an item is not evidence that a sale is being offered.", "Distinguish news, museum images, safety discussion, permitted accessories, and prohibited sale offers. Escalate ambiguous or high-impact decisions to trained reviewers with an appeal path."],
      capacity: ["Assume 1 million listings/day: about 11.6 average uploads/s and 116/s at a 10x peak. At 500 ms GPU inference per listing, a worker processes roughly 2/s before batching; 116/s needs at least 58 worker-equivalents before redundancy/headroom.", "Use a sub-second lightweight pre-publication screen and an asynchronous deeper review queue. Review capacity is part of the design, not an unlimited downstream sink."],
      data: ["Build policy-versioned labels for restricted object category, sale intent, jurisdiction, context, and final action. Include benign lookalikes and contextual negatives. Use authorized reviewer labels with adjudication and measure inter-reviewer agreement.", "Extract text/OCR, image embeddings, listing metadata, and limited authorized account-level abuse signals. Minimize personal information and avoid attributes unrelated to enforcement.", "Use seller-grouped and time-based splits to reduce leakage from repeated listings. Track novel content distributions and multilingual performance. Keep uncertain labels separate from confirmed policy violations."],
      model: ["Start with policy rules and a text/image classifier; add multimodal fusion to distinguish depiction from an offer to sell. Predict calibrated policy risk rather than converting any object detection into a ban.", "Train with class weighting or sampling for rare positives, then calibrate on the deployment class distribution. Use separate thresholds for allow/review/restrict; reserve automated restriction for well-validated high-confidence cases."],
      online: ["POST /listing returns listing_id and moderation_state. Object upload is isolated from model execution; a decision service consumes versioned evidence, emits action and reason_code, and records policy/model versions.", "Send medium-confidence cases to a prioritized review queue with evidence and uncertainty. Reviewer actions are authenticated and audited; appeals should reach a reviewer who can examine context, not merely rerun the same classifier."],
      metrics: ["Report precision/recall at each action threshold, PR-AUC, policy exposure per 1,000 listings, review rate, reviewer turnaround, and appeal reversal rate. Accuracy is misleading for rare violations.", "If prevalence is 1%, recall 90%, and false-positive rate 1%, then among 10,000 listings there are 90 true positives and 99 false positives: precision = 90/189 = 47.6%. A seemingly low false-positive rate can still overwhelm enforcement.", "Measure language, context, and item-category slices plus uncertainty intervals. Run shadow evaluation and reviewer audits before automatic enforcement; do not use aggregate metrics as evidence of equal error rates across groups."],
      risks: ["Queue overload can expose harmful listings or block legitimate ones. Bound queue age, add priority by potential harm, and choose a documented policy-approved degraded mode. Do not silently auto-allow all cases when the model fails.", "Protect reviewer access, retain only necessary evidence, and monitor appeal backlogs and policy drift. Keep training examples and enforcement internals access-controlled; publish user-facing policy and reasons rather than evasion-sensitive details."],
      tradeoffs: ["Higher recall increases review cost and false restrictions; choose thresholds with explicit harm and reviewer-capacity constraints. Multimodal models improve context but require more compute and careful explanation.", "Keep policy logic separate from learned evidence so a jurisdictional rule change can ship without retraining the whole model. Validate the combination, not only the classifier."],
      followups: [["What if a new policy is introduced?", "Version the policy, label a targeted audit set, shadow decisions, calibrate thresholds, and update reviewer guidance before enforcement."], ["How do you avoid banning educational content?", "Include contextual negatives, use sale-intent evidence, and route ambiguous content to review with an appeal process."], ["What is the launch gate?", "Predeclared precision/recall and review-capacity thresholds on representative slices, acceptable appeal errors, bounded decision latency, and a tested rollback."]]
    },
    {
      id: "bug-reporting", title: "Design a user bug reporting system",
      summary: "Capture reproducible evidence, detect duplicates, prioritize impact, and close the loop.",
      flow: [["Client SDK", "Consent + minimal diagnostic bundle"], ["Intake", "Validate, redact, durable receipt"], ["ML triage", "Deduplicate + classify + prioritize"], ["Issue tracker", "Route, owner, SLA"], ["Resolution", "Notify + verify recurrence"]],
      feedback: "Engineer merges, routing corrections, and confirmed fixes produce labels; user votes alone are not severity.",
      scope: ["Clarify mobile/web product, crash reports versus user-written bugs, attachment support, and whether ML is required. The core product must accept reports reliably even when triage models are unavailable.", "Return a tracking ID, allow status lookup, and connect users with resolved issues. Separate security reports into a restricted process. Do not ask users to upload credentials or unrelated private logs."],
      capacity: ["Assume 100,000 reports/day, about 1.16/s on average and a 100x incident spike of 116/s. At 2 MB/report, raw attachments total 200 GB/day before replication and retention.", "Acknowledge intake within 300 ms after durable metadata/queue commit; large attachments upload directly to object storage. Deduplication and routing can finish asynchronously within minutes."],
      data: ["Store report_id, tenant, consent, product/build version, platform, redacted stack signature, text, attachment references, status, and access scope. Use short-lived upload URLs, file limits, and malware scanning.", "Labels include confirmed duplicate pairs, component/owner, validated severity, fix version, and reopened status. A report that was closed without investigation is not automatically a negative training example.", "Split chronologically and group by underlying issue and release. Otherwise near-identical stack traces leak from train into test. Evaluate languages and reports with poor or missing diagnostics."],
      model: ["Start with deterministic stack/build signatures and keyword routing. Add embedding retrieval of likely duplicate issues followed by a pairwise duplicate classifier. Generate a suggested summary with references, never fabricated reproduction steps.", "Prioritize using affected unique users, crash severity, regression evidence, and business impact. Keep priority distinct from sentiment and duplicate probability. Low-confidence owner predictions go to a triage queue."],
      online: ["POST /reports with Idempotency-Key creates one report even after retries; GET /reports/{id} enforces tenant and reporter access. Persist intake and outbox atomically, then workers classify, index, and update issue links idempotently.", "Use a search/vector index for candidate duplicates and a source-of-truth issue database for status. A suggested merge must not destroy originals; keep reversible links and an audit log. Notify users after a verified resolution, not merely model classification."],
      metrics: ["Measure duplicate retrieval Recall@K, duplicate-merge precision, component macro-F1, time-to-correct-owner, time-to-triage, and severe-bug recall. A false merge is often costlier than a missed duplicate.", "If 80 of 100 real duplicate pairs are retrieved and 70 are correctly merged, retrieval recall is 80%, while end-to-end duplicate recall is 70%. Do not report the retrieval result as the final system result.", "Track intake success, queue age, cross-tenant access failures, user completion rate, reopened issues, and time to resolution. Compare against a rules-only baseline and audit representative low-priority reports."],
      risks: ["Crash storms create correlated duplicates; rate-limit abusive clients but preserve aggregated incident impact. Partition processing and deduplicate cheaply before expensive model calls.", "Redact secrets before indexing/model inference. Treat user text and logs as untrusted input; any summarizing LLM has no authority to run commands or change issue permissions. Delete attachments and derived index entries according to retention rules."],
      tradeoffs: ["Automatic merging saves time but can hide distinct regressions; begin with suggestions and high-precision reversible merges. Full diagnostic bundles help reproduction but increase privacy risk and storage cost.", "Keep asynchronous ML off the acceptance path. If embeddings fail, retain reports and use signature-based triage; visibly mark suggestions pending instead of losing the report."],
      followups: [["How do you handle duplicate retries?", "Deduplicate by tenant plus idempotency key and bind the key to a request hash; reject conflicting payload reuse."], ["How do you detect a newly introduced regression?", "Compare normalized incident rates by build and rollout cohort, accounting for active users and traffic, rather than raw report counts."], ["How do you validate an LLM summary?", "Check factual support against submitted evidence, require source references, and let engineers correct it; do not infer unseen stack frames or fixes."]]
    },
    {
      id: "spotify-hour", title: "Design Spotify recommendations from the most popular tracks in the past hour",
      summary: "Compute exact window semantics first, then personalize a fresh, diverse candidate pool.",
      flow: [["Play events", "Event ID, event time, qualified play"], ["Stream window", "Dedup + 60 one-minute buckets"], ["Top candidates", "Per region/category + global merge"], ["Personal rank", "Taste, novelty, availability"], ["Playlist", "Versioned snapshot + exposure"]],
      feedback: "Late events revise window counts; recommendations log the exact popularity snapshot used.",
      scope: ["Ask whether the request is a global top chart or personalized recommendations restricted to popular tracks. Design the latter, exposing an unpersonalized chart as a separate endpoint.", "Define a qualified play, bot filtering, geography, catalog rights, and what 'past hour' means. Use the rolling event-time interval (now - 60 minutes, now], not simply the current clock hour."],
      capacity: ["Assume 100 million qualified plays/hour = about 27,778 events/s. At 200 bytes/event this is 20 GB/hour before broker replication and indexes.", "Maintain per-track minute buckets with a watermark and explicit lateness bound, for example 5 minutes. Sixty 1-minute buckets approximate a continuously sliding hour unless boundary events are retained or finer buckets are used; disclose this accuracy/freshness trade-off."],
      data: ["Use event_id, track_id, event_time, ingest_time, country/rights region, and a pseudonymous listener ID where authorized. Deduplicate replayed events and distinguish client retries from separate qualified listens.", "Store count snapshots with window_end, watermark, region, aggregation version, and bot-filter version. Exposure/skip/completion logs support personalization; popularity counts should not be contaminated by duplicate telemetry.", "Train user/track embeddings and rankers on past windows only. Do not use the target-hour final counts as features for decisions made earlier in that hour. Test new tracks and bursts, not only historical hits."],
      model: ["Start with a rights-filtered top-K chart and genre diversification. Retrieve from global and per-region/genre popular pools, then personalize using user/track similarity and predicted qualified listening.", "Use exploration and artist caps to reduce rich-get-richer loops. Popularity is a feature or candidate constraint, not proof of personal relevance. Detect coordinated artificial streaming separately from ordinary repeat listening."],
      online: ["A partitioned stream aggregates track-minute counts, expires old buckets, and materializes rank snapshots. For an exact global top-K by track count, first compute complete per-track counts with track-key partitioning; then merge shard top-K lists. Arbitrarily truncated regional lists do not guarantee a global result when regional counts must be summed.", "GET /recommendations?window=1h&region=... reads a versioned candidate snapshot, filters licensing/unavailable tracks, ranks for the listener, and returns a stable cursor. Keep counts and rank snapshots consistent enough to explain displayed chart positions."],
      metrics: ["Validate rolling counts against a replayed batch oracle at the same event-time boundary, including duplicates, late arrivals, and expirations. Report count error, top-K overlap, watermark lag, and chart age.", "At 10:30, a track with 400 valid plays during (09:30,10:30] and 50 at 09:20 has count 400, not 450. At 10:31, subtract events leaving the left boundary and add newly included events; a TTL alone does not maintain the exact sum.", "Online measure qualified-listen rate, skip rate, discovery, artist/catalog coverage, retention, and serving latency. Slice by market and new users; monitor how recommendations themselves amplify popularity."],
      risks: ["Hot tracks cause skew; split hot-key partial aggregation and merge by track/time bucket. Recover from durable logs and checkpointed state, with idempotent outputs and replay tests.", "Rights removals must override cached rankings immediately. If stream freshness breaches the SLO, label the last complete snapshot and degrade deliberately rather than calling stale data 'past hour'."],
      tradeoffs: ["Exact rolling windows need more event state; time buckets reduce memory and update cost at a known boundary error. Approximate heavy-hitter sketches save memory but need measured recall/error and cannot support arbitrary exact deletions naively.", "Global popularity is cheap but narrow; per-market candidate pools improve relevance while complicating aggregation, rights filtering, and offline evaluation."],
      followups: [["What happens to an event arriving 10 minutes late?", "Apply the declared lateness policy: correct historical aggregates/backfill or quarantine for audit; do not silently mix inconsistent window definitions."], ["Can you merge regional top-100 lists to get the true global top-100?", "Not generally when one track's count is spread across regions and it is absent from every regional shortlist. Aggregate full per-track totals or use a provable distributed selection method."], ["How do you avoid a stale playlist during recovery?", "Serve the last completed, timestamped snapshot with a freshness indicator while replay catches up; alert and cap allowed staleness."]]
    },
    {
      id: "insurance-damage", title: "Estimate insurance claim size from photos of a damaged object",
      summary: "Separate visible damage, repair costs, coverage, and uncertainty; retain adjuster oversight.",
      flow: [["Claim intake", "Consent + guided multi-view photos"], ["Quality gate", "Blur, coverage, duplicates"], ["Vision", "Object/part + damage extent"], ["Cost model", "Parts, labor, region, date"], ["Adjuster", "Interval + evidence + escalation"]],
      feedback: "Final adjudicated repair outcomes arrive late and must be separated from initial estimates.",
      scope: ["Choose a domain such as vehicle exterior damage; a single model for cars, phones, and buildings is not a credible starting scope. Clarify whether the target is repair cost, covered payout, or total-loss probability; they are different labels.", "Use the output as decision support. Photos cannot establish hidden structural damage, full policy coverage, liability, or fraud. Require inspection or human review when evidence is insufficient or consequences are high."],
      capacity: ["Assume 50,000 claims/day x 8 images = 400,000 images/day, about 4.63 images/s average and 46.3/s at 10x peak.", "At 4 MB/image, raw storage is 1.6 TB/day before replication. Upload directly to encrypted object storage; asynchronous inference can target a 2-minute estimate rather than blocking a mobile upload."],
      data: ["Collect consented images, object make/model/year, damaged parts, repair operations, regional labor rates, estimate date, inspection findings, and final approved invoices. Record supplements separately from the original estimate.", "Label visible damage with expert adjudication and retain visibility/uncertainty flags. Remove personal identifiers, faces, plates, and unrelated documents where possible; enforce insurer/claim-level access.", "Split by claim and time, and test unseen shops, devices, object variants, and regions. Never let photos from one claim occur in both train and test. Adjust cost targets for inflation and changes in repair practices."],
      model: ["Start with a rules/price-table baseline for a scoped object class. Use image quality checks, part detection/segmentation, damage type/severity classification, then combine image features with structured attributes in a cost regression model.", "Predict a distribution or quantiles, not only a point estimate. Quantile loss can estimate lower/median/upper costs; validate interval coverage on held-out data and recalibrate when geography or pricing changes. High uncertainty triggers additional views or an adjuster."],
      online: ["POST /claims/{id}/photos creates upload slots; POST /claims/{id}/estimate queues a versioned job. GET /claims/{id}/estimate returns status, visible-damage evidence, cost interval, currency/date, limitations, and model/pricing versions.", "Use deterministic job keys for repeated submissions and image checksums for duplicate handling. Keep coverage calculation in an auditable policy service and never equate estimated repair cost with automatically owed payout."],
      metrics: ["Report MAE in currency, median absolute error, signed bias, and error by cost band. MAPE is unstable for near-zero claims; include quantile loss and interval coverage/width.", "For 100 audited claims, an intended 90% interval covering 83 actual costs has empirical coverage 83%, not 90%. Inspect coverage by damage severity and region, plus the width required to reach the target.", "Measure adjuster override rate, supplement rate, time-to-estimate, unnecessary inspections, and underestimation harm. Compare with expert-to-expert variability and calibrate to final mature outcomes, not only early reserves."],
      risks: ["Image quality, missing angles, hidden damage, and out-of-distribution objects warrant abstention. Do not infer wrongdoing from a model mismatch; send inconsistent evidence to authorized investigation with due process.", "Apply retention/deletion to originals, thumbnails, embeddings, and exported training sets. Monitor vendor pricing drift, privacy incidents, systematic underestimation, and accessibility of guided photo capture."],
      tradeoffs: ["End-to-end image-to-price models are simple to serve but harder to audit and update when labor rates change. A modular damage-plus-pricing design is more explainable but can propagate segmentation errors.", "Automating easy, low-uncertainty claims reduces turnaround; optimizing automation rate alone can hide expensive mistakes. Use selective prediction with an explicit human-review budget and harm guardrails."],
      followups: [["What if the photo looks undamaged but the repair is expensive?", "Hidden damage and policy context may dominate. Abstain or request inspection; do not force the image model to invent evidence."], ["Why not regress directly to payout?", "Payout also depends on coverage, deductible, liability, and adjudication. Keep physical cost estimation and policy decisions separate."], ["How do you update for inflation?", "Version regional price tables and cost date, monitor residual bias over time, and recalibrate against recent mature repairs."]]
    },
    {
      id: "chatbot-finetuning", title: "Design an LLM fine-tuning pipeline for a chatbot",
      summary: "Choose the right adaptation method, version every artifact, and gate releases with held-out evaluations.",
      flow: [["Goal + data", "Rights, redaction, task taxonomy"], ["Baseline", "Prompt/RAG versus fine-tuning"], ["SFT", "Masked assistant-token loss + adapters"], ["Optional preference", "DPO or separately justified RL"], ["Release", "Eval -> canary -> monitor/rollback"]],
      feedback: "User feedback enters a reviewed dataset queue; production conversations never automatically become training truth.",
      scope: ["Clarify domain, languages, tone, tool access, safety constraints, deployment budget, and desired behavior change. Use RAG for changing factual knowledge; fine-tuning is more appropriate for stable behavior, format, or domain task skill.", "Define success with representative conversations and a prompt/RAG baseline. Fine-tuning is not automatically the cheapest or safest answer, and it does not guarantee factual memory or permission enforcement."],
      capacity: ["Assume 100,000 curated conversations x 1,000 tokens = 100 million tokens; three full epochs process about 300 million tokens, excluding padding and packing effects.", "With eight GPUs sustaining 2,000 useful training tokens/s each, ideal token-processing time is 300,000,000/16,000 = 18,750 s, about 5.2 hours. Add evaluation, checkpointing, failures, and utilization overhead; measure actual throughput before promising a schedule."],
      data: ["Ingest only authorized data with provenance, usage rights, retention, and deletion policy. Redact personal/confidential fields before annotation or training. Deduplicate by conversation, customer/template, and near-duplicate text.", "Define role structure, expected tool behavior, refusals, and response quality. Separate train/dev/final test by time/customer/task where appropriate; freeze the final test and prevent benchmark contamination. Preserve hard negative and failure examples with reviewed corrections.", "Version dataset manifests, tokenizer/chat template, base-model revision, preprocessing, label policy, and sampling mix. Validate tool schemas and multi-turn sequence boundaries; packing must not introduce unintended cross-conversation attention or labels."],
      model: ["Start with parameter-efficient SFT such as LoRA when quality and hardware allow. Optimize negative log-likelihood on intended assistant output tokens, masking padding and user/system input tokens under the chosen objective. Verify the actual model/template masking convention.", "Use gradient accumulation for effective batch size, mixed precision, clipping, and monitored learning rate. Check overfitting, catastrophic forgetting, and base-capability regressions. Preference optimization is optional: DPO uses paired preferred/rejected responses with a reference policy; PPO additionally requires a justified reward/critic/rollout infrastructure.", "Checkpoint model/adapters, optimizer, scheduler, RNG, data position, and training configuration for reproducible recovery. Validate recovery on a small job before scaling; an adapter file alone is not a full training checkpoint."],
      online: ["A job API creates an immutable experiment with dataset/base/config IDs and an idempotency key. Orchestrate validation -> training -> artifact registration -> evaluation -> approval -> staged deployment.", "Serve a versioned model bundle with matching tokenizer, template, adapter/base, and tool schema. Roll out by tenant or user cohort; log output and tool decisions under privacy limits. Keep authorization and action confirmation outside the model."],
      metrics: ["Use held-out cross-entropy/perplexity for learning diagnostics, not as the chatbot's only success metric. Evaluate task success, grounded factuality, schema validity, refusal precision/recall, adversarial robustness, multi-turn coherence, and human preference with blinded rubrics.", "If average test cross-entropy is 1.2 nats/token, perplexity is exp(1.2) = 3.32. It is an effective uncertainty measure over token predictions, not a 3.32% error rate or proof of helpfulness.", "Report results by domain/language/context length; calibrate LLM judges against human labels and measure inter-rater agreement. Online track resolution rate, escalation, harmful action rate, p95 latency, token cost, and drift. Use frozen release gates and confidence intervals."],
      risks: ["Training on raw logs can leak sensitive material or reinforce prior mistakes. Use data approval, access control, contamination checks, and deletion lineage. Treat retrieved/training text as untrusted; keep executable tools in least-privilege services.", "Detect loss spikes, NaNs, stale checkpoints, broken masking, and dataset skew. Reject an artifact failing evaluation rather than silently promoting the last file written; support explicit failed-job status and audit logs."],
      tradeoffs: ["Full fine-tuning offers more capacity but costs memory and complicates model lifecycle; adapters reduce trainable state but still need quality validation and compatible base revisions.", "Prefer the smallest adaptation that beats the baseline under quality, safety, and cost constraints. Roll back model bundle and prompts/template together if a canary fails, while preserving experiment artifacts for investigation."],
      followups: [["Why can perplexity improve while chatbot quality falls?", "It measures next-token likelihood under the evaluation data. Narrow imitation, label style, or leakage may improve that score while harming reasoning, safety, or real task completion."], ["How do you recover exactly after a crash?", "Restore training state, RNG and data position, verify compatible code/config, and test for duplicated or skipped samples; state the limits of determinism."], ["When do you choose RAG instead?", "When the main gap is freshness or document access, and citations/permissions matter more than changing stable response behavior."]]
    },
    {
      id: "bank-fraud", title: "Design bank transaction fraud detection",
      summary: "Score under a hard deadline, use delayed labels correctly, and optimize loss with customer friction.",
      flow: [["Authorization", "Transaction + account context"], ["Features", "Point-in-time velocity + device"], ["Risk score", "Rules + calibrated model"], ["Decision", "Approve, step-up, or decline"], ["Outcomes", "Disputes + investigation + maturity"]],
      feedback: "Confirmed fraud and legitimate-user corrections arrive after authorization; pending transactions are not clean negative labels.",
      scope: ["Clarify card authorization versus bank transfers, transaction channels, response deadline, reversible actions, and applicable regulations. Separate fraud risk scoring from credit underwriting and AML investigation.", "Optimize expected financial loss under false-decline, challenge-rate, and latency constraints. Make high-impact actions auditable and provide appropriate customer verification and recovery paths."],
      capacity: ["Assume 100 million transactions/day = about 1,157 average transactions/s, with 10x peaks around 11,574/s.", "For an illustrative 100 ms p99 decision SLO, reserve 20 ms for features, 20 ms model/rules, 20 ms policy, and 40 ms network/headroom. Observe whole-request p99; adding per-component p99 values does not prove the total percentile."],
      data: ["Use amount/currency, merchant/channel, account history, authorized device signals, and time-window velocities. Keep protected or irrelevant personal attributes out of ad hoc feature engineering and audit proxy effects.", "Label confirmed fraud, confirmed legitimate, and unresolved transactions separately. Chargebacks arrive late and are incomplete; model label maturity and censoring. Declined transactions lack the same observable outcomes as approvals, creating selection bias.", "Train on point-in-time joins, split forward in time, and group entities to test generalization. Prevent future chargebacks or later account restrictions from leaking into historical features. Maintain an offline/online feature parity test."],
      model: ["Start with expert rules and a calibrated gradient-boosted tree. Add graph or sequence features only when incremental benefit justifies latency, explainability, and operational cost.", "Calibrate probabilities at production prevalence after any sampling. Use a policy that considers risk, amount, possible recovery, challenge cost, and false-decline cost. A challenge is a separate action with its own acceptance and fraud-prevention rates."],
      online: ["POST /risk-decisions accepts a transaction ID and idempotency key; repeated authorization retries reuse a compatible decision under a documented validity window. Read current velocity features, score, apply policy, and emit decision, reason codes, model and feature versions.", "Update streaming counters idempotently and reconcile with the ledger. Bound remote dependencies and cache safe stable features. Define a risk-tiered outage policy with the bank: not blanket fail-open or fail-closed for every amount/channel."],
      metrics: ["Measure PR-AUC, recall at a fixed false-positive/challenge rate, fraud amount prevented, expected net loss, false declines, calibration, and p99 latency. ROC-AUC alone can hide poor precision at rare fraud prevalence.", "Simplified two-action threshold: decline if p x fraud loss L exceeds (1-p) x legitimate-decline cost C. This gives p > C/(L+C); with L=100 and C=5, threshold is about 4.76%. Real policies must add recovery, challenge outcomes, regulation, and uncertainty.", "Replay mature historical windows and run shadow decisions before a guarded rollout. Measure cohort and channel outcomes with mature labels; avoid unconstrained exploration on high-risk transactions. Audit samples from both accepted and flagged traffic."],
      risks: ["Monitor feature lag, velocity-counter replay errors, model drift, fraud bursts, and merchant/channel shifts. Keep rule overrides versioned with expiration and peer approval.", "Encrypt financial data, minimize retention, restrict investigations by role, and record reasons and appeal/correction paths. Do not expose detection internals or mistake a risk score for proof of criminal intent."],
      tradeoffs: ["Graph/sequence models can improve coordinated-pattern detection but introduce freshness and serving complexity. A transparent, reliable baseline often wins early under a strict authorization deadline.", "Faster blocking may prevent losses while increasing customer friction and biased feedback. Jointly optimize approved legitimate volume, fraud loss, and verification burden rather than maximizing model recall."],
      followups: [["How do you train when labels arrive after 60 days?", "Use mature training windows, explicitly handle unresolved labels, and monitor early proxy signals separately from final fraud performance."], ["What if the feature store is unavailable?", "Apply the preapproved risk-tiered degraded policy, flag missing features, enforce deadlines, and alert; do not silently impute all missing behavior as normal."], ["How do you measure false declines?", "Use customer verification, investigations, and representative audits with selection-bias caveats; declined transactions do not reveal their counterfactual outcome automatically."]]
    },
    {
      id: "face-swap-lens", title: "Design a face-swap lens",
      summary: "Build a consent-based, low-latency visual effect with privacy and impersonation safeguards.",
      flow: [["Consent + camera", "Authorized participants/assets"], ["Track", "Faces, landmarks, temporal IDs"], ["Transform", "Pose/expression-aware effect"], ["Blend", "Occlusion + lighting + smoothing"], ["Render", "On-device preview + effect label"]],
      feedback: "Aggregate performance and opt-in quality reports improve the effect; raw faces are not uploaded by default.",
      scope: ["Limit scope to an opt-in entertainment lens using authorized participants or licensed assets. Do not support nonconsensual identity use, deceptive authentication, or impersonation. Clarify one face versus multiple faces and live preview versus offline export.", "Prioritize on-device processing and a clearly visible synthetic-effect indicator. Offer revocation, easy disablement, and deletion; avoid building a persistent face-identity database for a cosmetic feature."],
      capacity: ["At 30 frames/s, each frame has about 33.3 ms. An illustrative budget is 6 ms detection/tracking, 14 ms transformation, 7 ms blending/rendering, and 6.3 ms headroom.", "Measure end-to-end frame latency, thermal throttling, battery, and memory on supported devices. Detect on selected keyframes and track between them, with periodic re-detection when confidence falls."],
      data: ["Use consented/licensed data with varied poses, lighting, occlusion, skin tones, and device cameras. Record authorization, allowed usage, and retention. Keep evaluation identities distinct from training identities.", "Prepare landmark/segmentation/pose labels and temporal clips. Evaluate with glasses, facial hair, motion blur, multiple people, and partial faces. Avoid a test set consisting only of well-lit frontal portraits.", "Do not collect face embeddings for unrelated identity recognition. If an optional server path exists, require explicit consent, encryption, short retention, and deletion of derived artifacts."],
      model: ["Start with landmark-based geometric warping and blending as an understandable baseline. For richer effects, use a compact, licensed conditional image model with pose/expression controls and segmentation; details must remain within consented entertainment use.", "Train temporal consistency and reconstruction/perceptual objectives on authorized data. Distill and quantize only after checking visible artifacts and cohort quality. Use confidence gating instead of confidently rendering an incorrectly tracked face."],
      online: ["The camera pipeline checks effect authorization, detects/tracks landmarks, applies the effect, handles foreground occlusion, blends color/edges, and renders. Keep capture-to-display latency and audio/video synchronization bounded.", "Use local effect packages with signatures and versioned model/runtime compatibility. When tracking is lost, fade or disable the effect, not attach it to a bystander. Exports retain an effect label/provenance where supported."],
      metrics: ["Measure landmark error normalized by interocular distance, segmentation IoU, temporal flicker, tracking loss, frame latency/drop rate, battery use, and human-rated naturalness.", "For a 1,000-frame clip with 40 dropped frames, frame-drop rate is 4%. Average FPS alone can hide disruptive stalls; also report p95/p99 frame times and longest freeze.", "Slice by device class, lighting, motion, occlusion, skin tone, and accessibility needs using appropriately governed evaluation data. Evaluate consent UX and whether the effect remains visibly labeled; identity-similarity metrics are not a sufficient success criterion."],
      risks: ["Impersonation and nonconsensual use are core risks, not secondary ranking trade-offs. Restrict source assets, provide reporting, and prohibit use for authentication or deceptive media. Provenance/watermarks help but are not infallible defenses.", "Handle bystanders, minors, and biometric-like data conservatively. Do not silently switch to cloud processing when a device is too slow. Provide an explicit, lower-cost non-identity effect fallback."],
      tradeoffs: ["Higher fidelity increases compute and misuse risk; a stylized lens may satisfy the entertainment goal with fewer resources and clearer synthetic appearance.", "Frame skipping saves battery but worsens temporal alignment. Adapt quality to device capability with hysteresis and stable tracking, not abrupt per-frame model switching."],
      followups: [["How do you handle a hand covering a face?", "Use segmentation/occlusion masks and lower-confidence tracking; fade or disable rather than drawing facial content over the foreground."], ["What if the phone overheats?", "Reduce resolution or effect complexity with user-visible quality adaptation; stop the effect if the latency/thermal budget cannot be met."], ["Can a watermark guarantee safety?", "No. Combine consent, restricted assets, labeling, abuse reporting, and policy enforcement; do not claim perfect resistance to removal or deception."]]
    },
    {
      id: "community-moderation", title: "Design community-based message moderation",
      summary: "Combine model triage and trustworthy community review without equating majority votes with truth.",
      flow: [["Message/report", "Policy + language + context"], ["Triage", "Severity + uncertainty"], ["Review pool", "Independent, qualified reviewers"], ["Decision", "Evidence + quorum + escalation"], ["Appeal", "Audit + reviewer calibration"]],
      feedback: "Adjudicated audits update reviewer reliability and model labels; popularity does not define policy.",
      scope: ["Clarify whether the community flags harmful messages, writes context notes, or decides removal. Set policy categories, action severity, reviewer eligibility, decision deadlines, and appeal authority.", "For imminent/high-severity harm use trained safety staff and a documented urgent path. Do not wait for crowd consensus to resolve urgent risk or let a vote automatically justify a punitive action."],
      capacity: ["Assume 10 million messages/day with 0.5% reported: 50,000 reports/day. At three independent reviews/report, demand is 150,000 reviews/day.", "If 5,000 active reviewers complete 20 reviews/day, capacity is 100,000/day, leaving a 50,000-review daily deficit. Reduce unnecessary review through triage, add capacity, or revise workflow; a queue alone does not fix overload."],
      data: ["Store message/context references, policy version, reports, reviewer assignments, votes/reasons, adjudication, appeals, and action history. Limit reviewer exposure to necessary content and protect reporter identity.", "Use expert-adjudicated samples to estimate reviewer and model error, with uncertainty for new reviewers. Do not use raw removal decisions as unquestioned ground truth when those decisions came from the same model being trained.", "Split by conversation and time. Evaluate language/community slices, coded ambiguity, reclaimed language, disagreement, and cases targeted by coordinated reporting. Track label uncertainty rather than forcing every dispute into a binary label."],
      model: ["Use a baseline policy classifier for risk and a separate uncertainty estimate for routing. Community review adds context; it should not be treated as free annotation with perfectly independent voters.", "Assign independently and avoid showing prior votes before judgment. Calibrate reviewer reliability against adjudicated samples, use conflict-of-interest restrictions, and require cross-group agreement for selected contexts while retaining expert escalation."],
      online: ["POST /messages/{id}/reports is authenticated, rate-limited, and deduplicated by reporter/reason policy. A queue creates review tasks with access controls; append decisions to an audit log and apply actions idempotently.", "Enforce a finite state machine: pending -> under_review -> decision -> appealed -> adjudicated. Message deletion, edit, or policy changes can invalidate prior evidence and require a new version, not mutation of the old audit trail."],
      metrics: ["Measure harmful exposure per 1,000 message views, precision/recall by policy, time-to-action, appeal reversal, reviewer agreement, queue age, and unnecessary removals.", "If 900 of 1,000 audited removals were justified, removal precision is 90%; this does not measure recall among all harmful messages. Audit unreported and allowed traffic to estimate missed harms.", "Test brigade resistance through controlled simulations and permissioned audits, not harmful live experiments. Monitor reviewer concentration, correlated voting, language coverage, and disagreement that signals ambiguous policy."],
      risks: ["Coordinate-abuse defenses include reviewer independence, rate limits, assignment isolation, and expert review; do not publicly disclose evasion-sensitive trust thresholds. Reputation alone can entrench insiders and suppress minority communities.", "Protect reviewers from unnecessary harmful exposure, support wellbeing, and restrict sensitive queues. Maintain a rapid appeal path, reversible actions where possible, and transparent policy explanations."],
      tradeoffs: ["Crowd review scales context better than a model alone but is slower, biased, and susceptible to coordination. Expert-only review is costly; combine tiers based on harm, uncertainty, and reviewer capability.", "High agreement can mean genuine clarity or shared bias. Keep independent audits and diverse viewpoints rather than optimizing agreement as the sole quality metric."],
      followups: [["How do you handle a reporting brigade?", "Separate reports from evidence, limit duplicate influence, assign independent reviewers, and escalate suspicious correlated decisions without assuming every high-volume report is malicious."], ["Can highly reputable reviewers decide everything?", "No. Cap concentration, audit calibration, manage conflicts, and reserve expert authority for high-impact or ambiguous actions."], ["How do you measure missing harm?", "Sample ordinary unreported traffic for governed adjudication; reports alone are a selection-biased denominator."]]
    },
    {
      id: "instagram-ads", title: "Design an Instagram ad recommendation system",
      summary: "Separate eligibility, relevance, auction economics, pacing, and user-experience guardrails.",
      flow: [["Request", "User consent + slot + context"], ["Eligible ads", "Targeting, policy, budget"], ["Prediction", "pCTR, pCVR, quality"], ["Auction/pacing", "Value + constraints + frequency"], ["Impression", "Durable exposure + spend ledger"]],
      feedback: "Delayed attributed conversions update models; spend accounting must remain correct even if attribution changes.",
      scope: ["Clarify feed versus story ads, pricing model, advertiser objective, attribution window, and privacy restrictions. Design a plausible platform, not a claim about a company's proprietary auction.", "Balance advertiser value, platform revenue, and long-term user quality. Respect consent, ad policy, sensitive targeting restrictions, budget, pacing, and frequency caps before optimizing score."],
      capacity: ["Assume 1 billion ad opportunities/day = about 11,574 average requests/s and 115,741/s at a 10x peak. A 100 ms illustrative p99 auction budget requires bounded candidate retrieval and batched inference.", "With 10 million active creatives, scoring the entire catalog per request is infeasible. Retrieve a few thousand eligible candidates, filter cheaply, and score a smaller shortlist."],
      data: ["Log auction_id, impression_id, eligible candidate set or sampled audit context, bids, features, scores, winner, price, budget decisions, clicks, and delayed conversions. Keep causal attribution assumptions explicit.", "Train pCTR on true impressions with reliable click labels. For pCVR, handle delayed conversion maturity and distinguish post-click versus impression-conditional probabilities. Account for negative sampling and position/exposure bias.", "Separate training, calibration, and chronological test windows. Deduplicate events, protect advertiser/user identifiers, and apply consent/deletion to derived features. Do not use future attribution outcomes as serving-time features."],
      model: ["Start with logistic/boosted-tree CTR prediction and a rule-governed auction. Add multi-task or deep ranking only after checking calibration and incremental advertiser value.", "For an illustrative CPC bid, expected value per impression is pCTR x bid per click. For CPA bidding it can be pCTR x pCVR_given_click x bid per conversion, with consistent probability definitions. Quality adjustments, auction pricing, and pacing are separate policy choices."],
      online: ["GET /ads?placement=... retrieves policy-eligible, consent-compatible ads with valid campaign schedules. Fetch user/context and creative features, score, apply frequency caps, run the chosen auction, reserve budget, and return a creative plus signed tracking token.", "Use atomic budget reservations or bounded regional allocations to prevent overspend; reconcile impression/click billing idempotently using event IDs. Maintain creative review status outside stale embedding caches and make budget exhaustion immediately effective."],
      metrics: ["Evaluate log loss, calibration, PR-AUC, and ranking/value metrics by advertiser, placement, and new creative. An AUC lift with worse calibration can make bidding and pacing worse.", "For pCTR=0.02 and CPC bid=$1.50, expected value is $0.03/impression, or $30 per 1,000 impressions before adjustments. This is expected value, not automatically the auction price or realized revenue.", "Online measure incremental advertiser conversions/value where experimental design allows, revenue, spend/budget correctness, hides/complaints, organic engagement, retention, and tail latency. Consider auction interference; naive user-level tests may alter shared campaign budgets."],
      risks: ["Budget counter lag, duplicate billing, malicious creatives, and stale policy status are critical failure modes. Separate financial audit logs from best-effort analytics; reserve/release budget with reconciliation.", "Prevent sensitive targeting and cross-user feature leakage. Monitor click fraud and bot effects, but do not expose operational anti-abuse signatures. Keep ad explanations and sponsored labels clear."],
      tradeoffs: ["A more complex ranker may improve relevance but worsen tail latency and calibration. Budget pacing can sacrifice immediate value to deliver consistently throughout the day.", "Strong global budget coordination improves correctness but adds latency; bounded regional allocations can control maximum overspend while allowing local auctions. State the error bound and reconciliation behavior."],
      followups: [["Why is CTR alone insufficient?", "It can favor clickbait and ignore conversion value, advertiser ROI, user harm, and budget constraints."], ["How do you prevent budget overspend?", "Use authoritative atomic reservations or bounded allocations, idempotent billing, expiration/release rules, and ledger reconciliation."], ["Why is experimentation hard?", "Ads share budgets and auctions, so treatment changes the supply/value seen by control. Discuss cluster, switchback, or budget-isolated experiments and their assumptions."]]
    },
    {
      id: "facebook-next-post", title: "Design next-post logic for the Facebook news feed",
      summary: "Combine hybrid feed generation with session-aware ranking and stable pagination.",
      flow: [["Publish", "Post + audience + durable event"], ["Candidates", "Follow graph + pull hot creators"], ["Score", "Relationship, relevance, integrity"], ["Slate", "Diversity + seen filtering"], ["Next page", "Snapshot cursor + exposure"]],
      feedback: "Meaningful interactions and negative feedback train later models; permission changes apply immediately.",
      scope: ["Clarify a home feed of followed accounts/groups versus open discovery, chronological versus ranked mode, and what 'next' means after scrolling or refreshing.", "Optimize meaningful, satisfying interactions with privacy, integrity, diversity, and fatigue constraints. Likes and clicks are proxies; do not equate repeated emotional engagement with user wellbeing."],
      capacity: ["Assume 10 million users x 10 page fetches/day = 100 million/day, about 1,157 average requests/s and 11,574/s at 10x peak.", "A creator with 10 million followers creates 10 million fanout writes for one post under pure push. Use push for ordinary accounts and pull-on-read for very high fanout accounts; estimate the write amplification before choosing."],
      data: ["Store post metadata, audience version, author, timestamps, follow/block relations, engagement events, exposure position, and session IDs. Track edits/deletions and access changes through invalidation events.", "Construct labels from exposed posts with delayed meaningful interactions, hides, dwell quality, and surveys. Exclude impossible dwell telemetry and avoid labeling all unseen posts as negatives.", "Train with chronological, point-in-time graph and feature snapshots. Group related post/thread content and evaluate cold users, minority-interest communities, new authors, and language slices."],
      model: ["Begin with chronological follows plus coarse recency/relationship heuristics. Add candidate retrieval from follows, groups, and approved discovery channels, then a multi-task ranker for meaningful interaction and negative-feedback risk.", "Re-rank a slate with author/topic repetition caps, freshness, and seen-item constraints. Use current session context for the next post without allowing a single accidental click to redefine the entire long-term profile."],
      online: ["GET /feed?cursor=... merges precomputed inbox candidates with pulled hot-author posts, checks audience/block/deletion status, fetches features, ranks, and returns items plus an opaque snapshot cursor.", "Bind the cursor to user/session, ranking snapshot, and a continuation position, with expiry. A refresh starts a new snapshot. Log impressions only when actually shown, and tolerate deduplication by post ID when pull/push paths overlap."],
      metrics: ["Evaluate candidate recall and NDCG with a documented meaningful-interaction label. Track duplicate rate, missed fresh-follow posts, privacy leakage, and consistency across page boundaries.", "Online measure satisfaction, meaningful interactions, retention, hides/reports, creator distribution, and p95/p99 latency. A high click-through rate with rising hides is not a successful feed.", "For 1,000 served items with 15 repeated within the session, duplicate exposure rate is 1.5%. Keep this denominator distinct from duplicate candidates removed before serving."],
      risks: ["Changing permissions must override cached feeds and cursors. Recheck access on read and media delivery; a previously valid cached ID is not a permanent entitlement.", "Feed generation can lag during a celebrity post or graph change. Bound queue lag and pull missing recent content; fall back to an authorized chronological feed if scoring fails."],
      tradeoffs: ["Push minimizes read work but magnifies write/fanout costs; pull improves hot-author scalability but increases merge latency. Hybrid thresholds depend on observed follower/activity distributions.", "Stable pagination sacrifices some immediate freshness; constant reshuffling creates duplicates and skipped posts. Use explicit refresh boundaries and session snapshots, not an ever-changing score as the only cursor."],
      followups: [["How do you handle a celebrity post?", "Avoid per-follower fanout for extreme degrees; cache the author's recent posts and merge them on reads."], ["What if a post is deleted between pages?", "Recheck eligibility and skip it; accept a shorter page or backfill authorized candidates without returning deleted content."], ["How do you avoid repeated authors?", "Apply slate/session diversity constraints after scoring while preserving relevance and measuring the impact on satisfaction."]]
    },
    {
      id: "translation-model", title: "Design a model for translation",
      summary: "Choose language/domain scope, train aligned text carefully, and evaluate meaning rather than overlap alone.",
      flow: [["Input", "Language/script + segmentation"], ["Encoder", "Source meaning + context"], ["Decoder", "Target tokens + constraints"], ["Quality gate", "Confidence + terminology"], ["Output", "Text + review/abstention signal"]],
      feedback: "Reviewed corrections enter versioned parallel data; private customer text is not reused without authorization.",
      scope: ["Clarify language pairs, domain, sentence/document context, low-resource support, and online versus batch. High-stakes legal/medical translation requires expert review and explicit limitations.", "Distinguish building a translation model from training a giant general LLM. A pretrained multilingual encoder-decoder adapted to the domain is a credible baseline; include a commercial/open baseline comparison under the same privacy constraints."],
      capacity: ["Assume 10 million requests/day x 40 source tokens = 400 million source tokens/day, about 4,630 source tokens/s average; generated target tokens are additional compute.", "At 5x peak, plan for roughly 23,150 source tokens/s plus target decoding. Batch by sequence length within a bounded latency window; estimate GPU capacity from measured source/target-length throughput, not source tokens alone."],
      data: ["Use licensed parallel corpora with alignment, language-ID, deduplication, and quality checks. Remove mismatched pairs, contaminated benchmarks, and personal/confidential material. Keep domain and language provenance.", "Split by document/source and time, preserving whole conversations/documents. Build human-reviewed tests for names, numbers, negation, idioms, code-switching, terminology, and low-resource directions.", "Use appropriate subword tokenization and normalization without erasing meaningful accents or scripts. Back-translation can help scarce data, but mark synthetic provenance and evaluate whether errors propagate."],
      model: ["Use an encoder-decoder transformer with cross-attention and language/task identifiers for multilingual training. Teacher forcing minimizes target-token cross-entropy conditioned on source and prior target tokens; mask padding.", "Adapt a pretrained checkpoint with domain-balanced sampling and monitor high-resource language domination. At inference choose greedy or beam decoding with justified length handling; terminology constraints can preserve approved names/phrases.", "Document-level context improves pronouns and coherence but costs latency and privacy exposure. Apply explicit target-language and unsupported-input checks rather than assuming any output in the target script is a faithful translation."],
      online: ["POST /translate takes source/target language, text or document reference, domain/glossary version, and a request ID. Validate size/language support, segment safely, schedule inference, reassemble formatting, and return model/glossary versions.", "Preserve placeholders, numbers, and markup with a validated representation; do not execute input markup. Cache only consent-compatible exact requests with the correct tenant/model/glossary key. Offer abstention or human review for uncertain/high-risk cases."],
      metrics: ["Use BLEU and chrF for reproducible corpus-level overlap with stated tokenization, plus learned semantic metrics such as COMET under their model/version assumptions. None alone guarantees faithful meaning.", "Human raters score adequacy, fluency, terminology, and critical meaning errors using an explicit rubric. Report per language direction, domain, document length, and quality tier; aggregate averages hide weak low-resource directions.", "A translation changing 'do not take' to 'take' can look lexically similar while reversing meaning. Add targeted critical-error suites for negation, numbers, entities, and hallucinated content. Measure p95 latency, throughput, and cost per translated token."],
      risks: ["Detect unsupported languages, domain shift, hallucinations, omissions, and toxic or biased transformations. Source toxicity may require faithful translation with appropriate handling, not unannounced rewriting.", "Keep private documents isolated and encrypted, and define retention. When inference fails, return an explicit failure/review state rather than original text disguised as a successful translation."],
      tradeoffs: ["Beam search can improve some translation quality but increases decoding cost and may overfavor generic outputs. Use measured language-specific quality/latency curves.", "One multilingual model shares low-resource knowledge but risks interference; per-domain adapters improve specialization while multiplying deployment artifacts. Version tokenizer, base, adapters, and glossary together."],
      followups: [["Why not use BLEU alone?", "It measures reference overlap and can miss semantic reversals or penalize valid paraphrases. Add semantic metrics and expert critical-error review."], ["How do you handle a very low-resource language?", "Use carefully licensed multilingual transfer, balanced sampling, reviewed synthetic data, and explicit quality limits; do not promise parity without evidence."], ["How do you preserve a customer's terminology?", "Use a versioned glossary with constrained or controlled decoding and tests for term placement, grammar, and conflicting instructions."]]
    },
    {
      id: "instagram-stories", title: "Design the Instagram story feature",
      summary: "Design expiring media and audience semantics first, then rank story trays and sequences.",
      flow: [["Upload", "Signed multipart upload + validation"], ["Publish", "Metadata + audience + expires_at"], ["Fanout", "Follow graph + story tray"], ["Read/rank", "Permission + expiry + sequence"], ["Delivery", "CDN token + view event"]],
      feedback: "Qualified views, skips, exits, and replies improve ranking; expiration remains an authoritative serving rule.",
      scope: ["Clarify 24-hour stories, images/video, close-friends audience, ordering within an author's story, view receipts, replies, and archives. Keep live streaming and collaborative editing out of the first design.", "This is a product/serving design with an optional ML ranking layer. Separate ranking authors in a tray from ordering that author's individual story segments, which often preserve chronology."],
      capacity: ["Assume 1 million uploads/day x 10 MB = 10 TB/day raw ingestion. Three encoding variants at a combined 2x raw size add about 20 TB/day before replication.", "At 50 million story opens/day, mean open rate is about 579/s with large burst factors. CDN egress depends on watched duration and bitrate, not just metadata request count."],
      data: ["Story metadata includes story_id, author, audience policy/version, media variants, creation time, expires_at, moderation state, and archive policy. Keep view receipts and user-visible ordering semantics explicit.", "Ranking data includes actual exposures, segment watch fractions, skips/exits, replies, relationship strength, and freshness. A preloaded video is not necessarily a viewed story.", "Use chronological point-in-time labels and avoid feeding later replies/views into earlier ranking features. Test new users and authors and watch for private-audience leakage through shared features or caches."],
      model: ["Start with most-recent followed authors and chronological segments per author. Add tray ranking based on relationship, freshness, and predicted satisfying completion/reply, with author diversity and exposure caps.", "Model premature exits and fatigue, not completion alone: a two-second story is easier to complete than a long one. Keep policy, audience, and expiry as hard filters outside learned relevance."],
      online: ["Create an upload session, write media directly to object storage, transcode/scan asynchronously, then atomically publish metadata and an outbox event. GET /stories/tray returns authorized, unexpired authors; GET /stories/{author} returns ordered eligible segments.", "Use signed, short-lived media URLs bounded by audience and expiration. Recheck visibility on access. Expiration is enforced by expires_at on reads and token lifetime; background deletion/TTL is cleanup, not the only correctness mechanism."],
      metrics: ["Evaluate tray NDCG/recall, author coverage, qualified completion, skips/exits, meaningful replies, duplicate exposures, and low-latency first-frame delivery.", "At 2 Mbps, 10 seconds of fully viewed video is about 20 megabits = 2.5 MB before overhead. Estimate egress from actual rendition and viewing patterns; do not count every preload as full delivery.", "Track expired/private content served (target zero under the stated threat model), upload success, publish-to-visible delay, transcode queue age, view-receipt lag, CDN cache hit rate, and p95 start latency."],
      risks: ["Clock skew, stale tray caches, and long-lived CDN links can expose expired content. Use server-authoritative expiry, bounded tokens, and invalidation on deletion/audience change.", "Reconcile failed uploads and orphaned objects; do not publish unfinished encodings. Make archiving an explicit opt-in/product policy and distinguish access expiry from physical storage deletion."],
      tradeoffs: ["Aggressive prefetch improves startup but costs mobile data and can inflate view signals. Prefetch only likely next segments within user/network limits and log visibility separately.", "Push story-tray updates for ordinary authors and pull for hot authors. Strong privacy/expiry checks add work but cannot be traded away for a slightly better ranking metric."],
      followups: [["Why is TTL not enough for 24-hour expiry?", "Deletion is often asynchronous. Filter by authoritative expires_at and prevent cached media authorization from outliving the story."], ["What happens if an author changes the audience?", "Bump audience version, invalidate tray/access caches, and reject old tokens according to the policy; do not rely solely on prior fanout."], ["How do you rank individual segments?", "Usually preserve author chronology, using skip/navigation affordances; rank authors separately unless the product explicitly permits reordering."]]
    },
    {
      id: "video-translation", title: "Design a system to translate videos to a target language",
      summary: "Preserve timestamps and meaning across transcription, translation, subtitles, and optional authorized dubbing.",
      flow: [["Ingest", "Rights + media metadata"], ["ASR", "Speech, language, timestamps"], ["Translate", "Context + glossary + alignment"], ["Render", "Subtitles or authorized TTS"], ["QC/delivery", "Sync, completeness, review"]],
      feedback: "Segment-level corrections version the affected downstream artifacts; retries do not restart every completed stage.",
      scope: ["Clarify offline uploaded videos versus live streaming, subtitles versus dubbing, source/target languages, speaker handling, accessibility, and turnaround. Default to subtitles; dubbing uses licensed or explicitly authorized voices, not unconsented voice impersonation.", "Define word/segment timestamps, subtitle line constraints, audio synchronization, and human review for high-stakes material. Translating text accurately does not automatically produce a usable timed video."],
      capacity: ["Assume 10,000 uploaded video-hours/day. At 0.25 GPU-hours per video-hour for a measured pipeline stage, demand is 2,500 GPU-hours/day, or about 104 continuously busy GPUs before headroom.", "At 70% effective utilization, that stage needs about 149 GPUs; add separate capacity estimates for ASR, translation, and synthesis. Use measured stage-specific real-time factors and duration-based queue priorities."],
      data: ["Store job_id, source asset checksum, rights/consent, language pair, track metadata, speaker/timestamp segments, transcript revision, glossary, and model versions. Keep each derived artifact tied to its source and revision.", "Train/adapt ASR with authorized accents/noise/domain data, translation with aligned text, and TTS with licensed voices. Split by speaker/document/program and test audio conditions, names, code-switching, and specialized terminology.", "Represent uncertainty and inaudible spans explicitly; do not let an uncertain transcript become confidently invented translation. OCR/on-screen text is a separate optional track with its own quality and rights considerations."],
      model: ["Use voice activity detection and ASR with timestamps/diarization where needed. Translate contextually across segments without losing source-to-target alignment. A modular pipeline makes errors attributable; end-to-end speech translation may help but needs equivalent timing and audit evaluation.", "For dubbing, generate authorized TTS and fit speech to sensible segment timing using bounded rate adjustments or rephrasing reviewed for meaning. Do not stretch every translated sentence into the original duration regardless of intelligibility.", "Preserve speaker turns, silence, sound cues, and accessibility captions where required. Keep visual lip manipulation out of scope unless explicitly consented and separately governed."],
      online: ["POST /video-jobs creates an idempotent job with asset checksum and language/config versions. An orchestrator runs ingest -> ASR -> translation -> subtitle/dub -> mux -> quality checks, persisting stage artifacts and status.", "Use content-addressed, versioned artifacts so a corrected transcript invalidates only dependent translation/render stages. Support cancel/retry and GET /video-jobs/{id} progress; partial results must clearly indicate missing segments and review status."],
      metrics: ["Measure ASR word/character error rate by language and audio condition; translation semantic/critical-error quality; subtitle reading speed, line breaks, timing overlap, and coverage; dub naturalness and synchronization.", "If 100 reference words have 5 substitutions, 3 deletions, and 2 insertions, WER = (5+3+2)/100 = 10%. WER does not measure translation quality, and names/negations may be more consequential than common-word errors.", "Report end-to-end human adequacy, omitted/extra segments, time-to-complete per video-hour, cost/video-hour, failure/retry rate, and timestamp drift. Good ASR plus good text translation scores do not prove good end-to-end dubbing."],
      risks: ["Noise, overlapping speech, language misidentification, timestamp drift, and missing audio tracks must produce explicit quality flags. Request review or fail a segment rather than replacing unintelligible audio with invented speech.", "Enforce media/voice permissions, encryption, retention, and deletion across intermediate assets. Label translated/dubbed outputs and preserve provenance. Large files need checksums, bounded uploads, malware checks, and job quotas."],
      tradeoffs: ["Modular stages allow debugging and targeted retries but compound errors and latency. End-to-end models simplify some interfaces while making attribution and controlled edits harder.", "Batch processing can maximize GPU utilization; live translation needs incremental ASR, bounded lookahead, and a different latency/quality contract. Do not claim an offline design meets a live subtitle SLO."],
      followups: [["What if translation is longer than the original speech?", "Use readable subtitle timing or authorized, intelligible dubbing adjustments with reviewed rephrasing; do not indiscriminately accelerate audio."], ["How do you retry a three-hour video?", "Checkpoint segments and stage artifacts with deterministic IDs, then recompute only failed or invalidated dependencies."], ["How do you debug a mistranslated name?", "Trace source audio -> ASR segment -> glossary/version -> translated text -> synthesis; correct the earliest erroneous stage and invalidate dependents."]]
    }
  ];

  const concepts = [
    {
      id: "requirements-capacity", title: "Requirements, capacity, and SLOs",
      summary: "Turn a vague product into measurable behavior, load, and reliability budgets.",
      flow: [["Scope", "Three core user actions"], ["Load", "QPS, bytes, skew, growth"], ["SLO", "Latency, availability, correctness"]],
      explanation: "Functional requirements describe what users can do; non-functional requirements define measurable qualities. Separate average traffic from peak traffic, reads from writes, metadata from media, and throughput from concurrency. Declare every guessed number as an assumption, then explain which architectural choice it changes.",
      example: "10 million daily users x 20 reads/day = 200 million/day = about 2,315 reads/s. A 10x peak is about 23,150/s. At 2 KB/response, peak payload egress is about 46 MB/s before protocol overhead. Little's law L = arrival rate x mean time gives about 2,315 in-flight requests at 23,150/s and 100 ms mean latency, assuming a stable system.",
      question: "Can a service with 99.9% monthly availability tolerate a one-hour outage?",
      answer: "In a 30-day month, a time-based 99.9% objective permits 43.2 minutes of unavailable time. One hour exceeds it. Request-based availability and exclusions can change the calculation, so state the SLI definition.",
      trap: "Do not size hardware from average QPS alone or add p99 component latencies and call the sum an end-to-end p99 guarantee."
    },
    {
      id: "networking-balancing", title: "DNS, load balancing, and service communication",
      summary: "Trace how a client reaches a healthy service and what a network failure actually means.",
      flow: [["Resolve/connect", "DNS + TCP/QUIC + TLS"], ["Balance", "L4 connections or L7 requests"], ["Service call", "Deadline + auth + bounded retry"]],
      explanation: "DNS resolves names and caches answers according to resolver behavior and TTLs; it is not an instantaneous failover switch. A layer-4 balancer routes transport connections, while a layer-7 proxy can route HTTP requests by host/path and apply request policy. Round-robin is simple; least-connections or load-aware routing can help uneven workloads. Health checks, connection draining, and outlier detection prevent sending new work to an unhealthy backend. REST/HTTP commonly exposes resources; gRPC adds typed RPC contracts and efficient streaming. Neither protocol removes the need for versioning, authorization, deadlines, and safe retries.",
      example: "40,000 concurrent WebSockets across 20 gateways average 2,000 connections/gateway, but connection count is not equal to CPU load when some clients send much more. Removing a gateway from new-request routing should drain or deliberately reconnect existing sessions, not assume all connections migrate automatically. HTTP keep-alive and multiplexing can also concentrate traffic, so test actual proxy/connection behavior.",
      question: "Why does changing DNS not instantly fail over every client?",
      answer: "Resolvers may retain cached answers, clients may keep long-lived connections, and some callers have delayed refresh behavior. Combine health-aware routing, bounded connection lifetimes/draining, client reconnect/backoff, and explicit backend ownership/fencing where correctness requires it. DNS changes alone cannot prevent an old primary from writing.",
      trap: "A successful network connection does not prove a request committed. Retrying a timed-out mutation still requires idempotency, and a load balancer is not a transaction coordinator."
    },
    {
      id: "apis-idempotency", title: "APIs, pagination, and idempotency",
      summary: "Make retries safe and pagination stable before adding more services.",
      flow: [["Client", "Request + idempotency key"], ["Commit", "Unique key + request hash"], ["Retry", "Same durable result"]],
      explanation: "Define resource IDs, authentication, request/response fields, errors, and consistency guarantees. An idempotency key identifies one intended operation within a documented scope and retention window. Persist the key, request hash, and result atomically with the operation or its durable state machine.",
      example: "POST /payments with key K and amount 10 creates one logical payment. A retry of the same payload returns its result; reusing K for amount 20 must return a conflict. For a changing feed, an opaque cursor can encode snapshot and last sort tuple, avoiding offset drift.",
      question: "Why is retrying a timed-out POST dangerous even if the server returned no response?",
      answer: "The server may have committed before the response was lost. Query by operation ID or retry with the same idempotency key. A timeout is an unknown outcome, not proof the operation failed.",
      trap: "A random request ID used only for logging does not deduplicate side effects; offset pagination is not stable under concurrent inserts."
    },
    {
      id: "storage-indexes", title: "SQL, NoSQL, schemas, and indexes",
      summary: "Choose storage from access patterns and invariants, not a universal SQL-versus-NoSQL rule.",
      flow: [["Queries", "Keys, ranges, joins, updates"], ["Schema", "Constraints + ownership"], ["Indexes", "Read benefit vs write cost"]],
      explanation: "Relational stores support constraints, joins, and transactions; key-value, document, wide-column, and search stores optimize different access patterns. Several NoSQL databases also support transactions and strong reads. Keep one authoritative record and deliberately maintain secondary read models.",
      example: "For per-user messages ordered by time, an index on (conversation_id, sequence_number) supports range pagination. A separate index on author_id helps a different query but adds write amplification and storage. Validate query plans and cardinality rather than indexing every field.",
      question: "Would you store video bytes in the same SQL row as feed ranking metadata?",
      answer: "Normally store large immutable media in object storage/CDN and metadata, ownership, and lifecycle state in the database. Use an explicit publish state machine so a metadata row does not expose an incomplete upload.",
      trap: "Calling a store 'eventually consistent' or 'transactional' without specifying operation, scope, configuration, and failure behavior is incomplete."
    },
    {
      id: "replication-cap", title: "Replication, consistency, and CAP",
      summary: "State which reads and writes must agree, especially during a network partition.",
      flow: [["Leader write", "Commit/replication policy"], ["Replica read", "Possible lag"], ["Partition", "Reject or accept divergent work"]],
      explanation: "Replication adds redundancy and read capacity, but asynchronous replicas can lag. Linearizability makes operations appear in a single real-time order; eventual consistency allows convergence after updates stop. Read-your-writes is a narrower session guarantee. CAP addresses the impossibility of simultaneously guaranteeing linearizable consistency and availability during a partition under its definitions, not an always-on menu of any two letters.",
      example: "An inventory purchase needs an atomic stock invariant, while an analytics chart may tolerate a minute of lag. A user's just-published post may require session read-your-writes even if other users see it later. Choose guarantees per operation.",
      question: "If there are three replicas, do W=2 and R=2 automatically guarantee linearizable reads?",
      answer: "Intersecting quorums help, but are not enough alone: versions, concurrent writes, leader/consensus protocol, read repair, and failure assumptions matter. Do not equate quorum arithmetic with a full consistency proof.",
      trap: "Availability is not durability; a responsive replica can serve stale data, and a durable write can temporarily be unavailable."
    },
    {
      id: "partitioning", title: "Sharding, hot keys, and rebalancing",
      summary: "Distribute data without making the busiest tenant or key everyone's bottleneck.",
      flow: [["Partition key", "Access locality + skew"], ["Shard map", "Hash/range + virtual nodes"], ["Rebalance", "Copy, catch up, cut over"]],
      explanation: "Hash partitioning spreads keys, while range partitioning supports locality and scans but can create hot ranges. Consistent/rendezvous hashing reduces remapping when nodes change; virtual nodes improve balance but cannot split one extremely hot key by themselves. Co-locate transactions that share an invariant when practical.",
      example: "Partitioning all events by country puts a large market on one shard. Partition by track_id for complete per-track counts; use partial salted aggregates for a viral track, then merge by track and time bucket. Salting helps writes but adds read/merge complexity.",
      question: "How do you move a shard without losing concurrent writes?",
      answer: "Copy a snapshot, stream changes from a known log position, verify catch-up, switch routing with a versioned ownership change, and retain a bounded rollback path. Fence stale writers.",
      trap: "Adding replicas does not remove a single-leader write bottleneck; choosing a shard key only by uniformity can make every query scatter-gather."
    },
    {
      id: "caching-cdn", title: "Caches, CDNs, and invalidation",
      summary: "Cache the right identity and define what staleness is acceptable.",
      flow: [["Lookup", "Tenant + object + version key"], ["Miss", "Coalesce + source read"], ["Invalidate", "TTL/version/event + authorization"]],
      explanation: "Cache-aside reads on a miss then fills; write-through updates the cache with writes; write-behind risks loss unless durable. CDNs cache public or authorized media near users. Specify TTLs, eviction, invalidation, negative caching, and behavior under source failure. A cache is not the source of truth for critical invariants.",
      example: "At 10,000 reads/s and 95% hit rate, source load is roughly 500 reads/s, excluding write and refill overhead. If all popular entries expire together, the miss burst can exceed this dramatically. Use TTL jitter, request coalescing, and bounded stale-while-revalidate only where safe.",
      question: "Can you cache a private story for 24 hours and rely on TTL to enforce access?",
      answer: "No. Audience changes, deletion, and expiry need authoritative authorization and appropriately bounded tokens/cache invalidation. Retention TTL is cleanup, not a permission guarantee.",
      trap: "Never key a personalized response by URL alone if different authenticated users can receive different data."
    },
    {
      id: "queues-outbox", title: "Queues, outbox, retries, and deduplication",
      summary: "Expect duplicate delivery and make side effects safe.",
      flow: [["DB transaction", "Business row + outbox"], ["Relay", "Publish with stable event ID"], ["Consumer", "Deduplicate + side effect + progress"]],
      explanation: "A queue decouples work and absorbs bursts; it does not create infinite processing capacity. At-least-once delivery means a worker can receive the same event again after a crash. A transactional outbox avoids the database-write/message-publish dual-write gap. Consumers still need idempotent application or transactional deduplication with their side effect.",
      example: "If 1,000 jobs/s arrive and workers complete 800/s, backlog grows by 200/s or 720,000/hour. Retry with bounded exponential backoff and jitter; quarantine poison jobs in a dead-letter workflow with alerts and a replay procedure.",
      question: "A worker sends an email and crashes before acknowledging. Can the queue guarantee the email is never repeated?",
      answer: "Not by itself. Use a provider-supported idempotency key or accept/document possible duplicate delivery and reconcile. An external side effect outside the consumer transaction is not magically exactly-once.",
      trap: "A dead-letter queue without ownership, alerting, retention, and replay is a silent failure sink."
    },
    {
      id: "streams-windows", title: "Streams, event time, watermarks, and top-K",
      summary: "Define time and replay semantics before claiming a real-time result.",
      flow: [["Events", "Event time != arrival time"], ["State", "Windows + dedup + checkpoint"], ["Materialize", "Versioned output + watermark"]],
      explanation: "Processing time is when a worker sees an event; event time is when it happened. Watermarks estimate progress but do not prove all earlier events have arrived. Declare allowed lateness, correction policy, and whether windows are tumbling, sliding, or session-based. Checkpoint source positions and state together under the engine's guarantees.",
      example: "A 60-minute rolling music chart can use minute buckets with known boundary error. Duplicate event IDs must not inflate counts. Expiring one event or bucket requires subtracting its contribution; merely putting a TTL on an accumulated counter is incorrect.",
      question: "Is the union of per-region top-10 lists guaranteed to contain the global top-10 by total plays?",
      answer: "No. A globally popular track may rank 11th in every region but have a large summed total. Compute full per-track totals or use a distributed selection method with an explicit guarantee/error bound.",
      trap: "A low queue lag does not prove event-time completeness; measure watermark lag and late-event behavior too."
    },
    {
      id: "rate-limits", title: "Rate limiting and overload control",
      summary: "Protect capacity while defining bursts, fairness, and distributed error bounds.",
      flow: [["Admission", "User/tenant/global quota"], ["Limiter", "Token bucket or window"], ["Overload", "429 + backoff + priorities"]],
      explanation: "A token bucket refills at rate r up to capacity B and permits controlled bursts; a leaky bucket smooths output; fixed windows are cheap but have boundary bursts; sliding windows cost more state. Distributed enforcement needs atomic updates or bounded regional allocations. Rate limits and concurrent-work limits solve different overload problems.",
      example: "A full bucket with B=100 and refill r=10/s permits 100 immediate unit requests, then roughly 10/s over time. It does not mean every one-second interval permits at most 10. Large inference jobs may consume weighted tokens plus a concurrency slot.",
      question: "What do you do when a shared limiter is unavailable?",
      answer: "Use a documented per-endpoint risk policy: bounded local quotas can protect read availability, while high-risk financial or administrative actions may reject. Alert and reconcile; never apply one silent default everywhere.",
      trap: "A global quota copied in full to three regions can allow roughly triple the intended burst."
    },
    {
      id: "transactions", title: "Transactions, isolation, and sagas",
      summary: "Protect invariants locally; orchestrate reversible cross-service work explicitly.",
      flow: [["Invariant", "Atomic condition + update"], ["Commit", "Isolation + uniqueness"], ["Cross-service", "Saga + compensations"]],
      explanation: "ACID transactions protect a defined database scope. Isolation levels determine anomalies such as lost updates and write skew; a transaction alone does not imply serializable behavior. Use conditional writes, uniqueness constraints, locking, or serializable transactions for the actual invariant. Cross-service sagas coordinate durable steps and compensations, not a universal rollback of reality.",
      example: "To reserve the last seat, atomically update inventory where remaining > 0 and verify one row changed. Reading remaining=1 and later writing 0 in two independent requests can oversell. A payment refund compensates a charge but does not erase the original financial event.",
      question: "Can a saga guarantee a delivered notification or shipped parcel is undone?",
      answer: "No. Some side effects are irreversible. Delay irreversible steps until prerequisites are durable, design compensating business actions, and expose exception states for human handling.",
      trap: "Do not use a cache lock without fencing/expiry semantics as a complete substitute for a durable invariant."
    },
    {
      id: "search-geo", title: "Search, inverted indexes, and geographic queries",
      summary: "Use indexes for candidate retrieval, then verify authoritative eligibility.",
      flow: [["Source DB", "Authoritative documents/places"], ["Index", "Terms, vectors, geo cells"], ["Query", "Retrieve -> filter -> rank"]],
      explanation: "An inverted index maps terms to document postings; vector indexes support semantic similarity; geo indexes prune by spatial cells or bounding regions. These are usually derived read models with ingestion lag. Separate retrieval quality from ranking quality and apply final permission/deletion checks against valid state.",
      example: "A nearby-place search can fetch adjacent geographic cells, then compute exact distances and opening status. A vector top-100 search may miss an exact product code, so combine lexical and semantic channels with measured recall.",
      question: "A user deletes a private document but it still appears in search. What failed?",
      answer: "Either deletion propagation is late or serving relied solely on the index. Remove/mark indexed content and enforce authoritative access checks; include caches, snippets, vectors, and downstream copies in deletion lineage.",
      trap: "Similarity is not authorization, and an ANN index returning K items does not prove it found the true nearest K."
    },
    {
      id: "blob-media", title: "Object storage, uploads, and media delivery",
      summary: "Keep large bytes off application servers and publish only verified objects.",
      flow: [["Upload session", "Scoped signed parts"], ["Verify", "Checksum + size + scan"], ["Publish", "Metadata + CDN authorization"]],
      explanation: "Use object storage for large immutable bytes and a metadata service for ownership, version, status, and permissions. Multipart upload supports retryable chunks; a final manifest/checksum validates completeness. Signed URLs must be scoped, short-lived, and bound to the intended operation. CDNs accelerate delivery without replacing authorization policy.",
      example: "A 1 GB file at 10 Mbps takes about 800 seconds before overhead. A single app-server request is a fragile transport. Upload parts directly, retry missing parts, finalize once, and clean orphaned parts under a retention policy.",
      question: "When is an uploaded video visible to viewers?",
      answer: "After integrity checks, scanning/moderation as required, essential encodings, and an atomic publish transition. Keep uploading/processing/ready/failed states explicit.",
      trap: "An uploaded object existing in a bucket does not mean the user owns it or that it is safe to serve."
    },
    {
      id: "realtime", title: "WebSockets, ordering, delivery, and presence",
      summary: "A live connection is transport, not durable message history.",
      flow: [["Gateway", "Authenticated connection"], ["Message log", "Conversation order + durable ack"], ["Reconnect", "Cursor + dedup + replay"]],
      explanation: "WebSockets provide bidirectional transport; server-sent events suit server-to-client streams. Durable messaging needs a stored event, acknowledgement semantics, replay cursor, and deduplication. Use per-conversation sequence numbers rather than pretending there is one cheap global order. Presence is usually an expiring approximate signal.",
      example: "A server acknowledges a message only after durable acceptance under the specified replication policy. If the socket disconnects before the ack arrives, the client retries with the same message ID. Reconnect starts after the last confirmed conversation sequence.",
      question: "Does TCP guarantee a chat message appears exactly once after reconnect?",
      answer: "No. A new connection does not preserve application delivery state. Persist message IDs/sequences, deduplicate retries, and define sent/delivered/read as distinct states.",
      trap: "An 'online' flag is not proof the recipient has read or even received the message."
    },
    {
      id: "multiregion", title: "Multi-region systems, RPO, and RTO",
      summary: "Specify failover correctness and data-loss tolerance, not only replica count.",
      flow: [["Primary region", "Write ownership"], ["Replica region", "Replication + lag"], ["Failover", "Fence, promote, verify, route"]],
      explanation: "Recovery point objective (RPO) bounds tolerated data loss; recovery time objective (RTO) bounds restoration time. Active-active reads are simpler than active-active writes to the same invariant. Cross-region consensus adds latency; asynchronous replication can lose recently acknowledged data during disaster. State assumptions and test failure drills.",
      example: "A 5-minute RPO can tolerate loss of up to five minutes of recent changes under the recovery contract; it does not mean recovery finishes in five minutes. A 30-minute RTO is a separate restoration target.",
      question: "How do you avoid two primaries accepting conflicting writes during failover?",
      answer: "Use durable ownership/consensus and fencing tokens, revoke or reject stale leaders, and route writes only after promotion is safe. DNS changes alone do not fence the old writer.",
      trap: "Backups are not tested recovery; replicate corruption/deletion protection and restoration drills are also necessary."
    },
    {
      id: "observability", title: "Observability, backpressure, and reliability",
      summary: "Watch user-visible success and tail behavior, then connect it to internal causes.",
      flow: [["SLIs", "Success, latency, correctness"], ["Diagnosis", "Metrics + traces + sampled logs"], ["Control", "Deadlines, queues, circuit breakers"]],
      explanation: "Define user-visible SLIs and error budgets. Metrics show trends, traces show request dependency paths, and logs provide event evidence under privacy limits. Propagate deadlines, bound queues/concurrency, and use backpressure rather than allowing unlimited work. Retries need a shared time/attempt budget to avoid amplifying an outage.",
      example: "If one request makes three serial calls each retried three times, a failure can multiply backend work and exceed the user deadline. Use bounded attempts, jitter, circuit breaking, and a fallback only if it preserves the product's correctness contract.",
      question: "Average latency is 50 ms but users complain. What do you inspect?",
      answer: "p95/p99 and timeout rate by region/device/cohort, queue delay, dependency traces, long-tail payloads, and client-perceived latency. Averages can hide severe stalls.",
      trap: "A healthy dashboard of HTTP 200s can conceal stale or unauthorized data; include semantic correctness and freshness."
    },
    {
      id: "security-privacy", title: "Authorization, privacy, and abuse-resistant design",
      summary: "Authenticate identity, authorize every resource, and minimize sensitive data.",
      flow: [["Identity", "Authentication + scoped tokens"], ["Resource", "Tenant/object/action authorization"], ["Lifecycle", "Audit, retention, deletion"]],
      explanation: "Authentication proves an identity; authorization decides an allowed action on a resource. Enforce object/tenant access on reads, writes, background jobs, exports, and media links. Use least privilege, secret management, encryption in transit/at rest, input validation, upload limits, and auditable administrative actions.",
      example: "An authenticated request for /claims/123 still needs access to claim 123. A vector search result, guessed object ID, or previously cached URL grants no entitlement. A deletion request should cover objects, thumbnails, features, indexes, and training lineage under the stated policy.",
      question: "Can you send a user's bug attachment to an LLM because the user clicked submit?",
      answer: "Not automatically. Verify purpose, consent/contract, data minimization, redaction, processor restrictions, retention, and access controls. Treat the attachment as untrusted content, not authority to execute tools.",
      trap: "A model's refusal behavior or a prompt instruction is not an authorization boundary."
    }
  ];

  const software = [
    {
      id: "url-shortener", title: "Design a URL shortener", source: "bitly",
      summary: "Make short codes unique, redirects fast, and revocation authoritative.",
      flow: [["Create API", "Validate URL + quota"], ["Code allocation", "Random code + unique insert"], ["Mapping DB", "Destination + owner + expiry"], ["Redirect", "Cache -> source -> 302"], ["Events", "Async click analytics"]],
      feedback: "Revocation invalidates caches; click analytics are not on the redirect's critical path.",
      scope: ["Support creating a short link, resolving it, optional custom aliases/expiry, and owner deletion. Ask whether analytics, account management, and editable destinations are core or follow-up scope.", "Define acceptable redirect latency, link lifetime, malicious-link handling, and privacy. A short link is public unless explicitly designed otherwise; unguessability is not authorization."],
      capacity: ["Assume 10 million new links/day and 1 billion redirects/day: about 116 creates/s and 11,574 redirects/s on average, with independent peak factors.", "Seven base62 characters give 62^7 = 3,521,614,606,208 possible codes. Random collisions remain possible; enforce uniqueness and retry. At 1 KB/mapping, 10 million/day adds about 10 GB/day before indexes and replicas."],
      data: ["Use code as a unique key with destination, owner, created_at, expires_at, status, and destination version. Index owner/creation time only if management queries require it.", "Keep analytics in an event stream and aggregate store, not a row updated synchronously on every redirect. Minimize IP/referrer retention and define what a unique click means."],
      model: ["Allocate random codes with sufficient entropy and a database uniqueness constraint, or discuss an ID allocator plus base62 encoding with predictability/range-allocation trade-offs. Custom aliases use the same atomic uniqueness rule.", "Cache mappings by code/version. For an editable or revocable destination prefer redirect semantics with a controlled cache lifetime; permanent 301 caching can make later changes difficult to enforce. Explain the chosen redirect/status policy."],
      online: ["POST /links with an idempotency key validates allowed schemes, length, ownership, and alias availability, then inserts mapping and returns a short URL. Avoid fetching arbitrary destination URLs on the request path; any preview scanner needs isolated egress controls.", "GET /{code} reads cache/source, verifies status/expiry, and redirects. A bounded asynchronous event records the click. Unknown, expired, disabled, and temporarily unavailable states should have explicit semantics."],
      metrics: ["Measure successful valid redirects, p95/p99 latency, source/cache error rate, cache hit ratio, link-creation conflicts, and revocation propagation time. Do not count disabled links as availability failures without defining the SLI.", "At a 95% hit rate, 100,000 redirect requests/s imply about 5,000 source reads/s under steady state, but expiration storms need extra protection. Test hot links, cold cache, source failover, collision retries, and concurrent alias creation."],
      risks: ["A viral link is a hot key; replicate immutable cached mapping and coalesce refills. Use negative caching with a short TTL to avoid repeated absent-key reads without hiding newly created aliases.", "Scan for abuse with clear policy, revoke unsafe links, and protect administrative actions. Cache invalidation and expiration checks must prevent revoked destinations from remaining indefinitely accessible."],
      tradeoffs: ["Global atomic creation can cost latency; regional code ranges or random codes with authoritative conflict checks reduce coordination. Multi-region editable aliases still require an ownership/conflict policy.", "Cached stale redirects improve availability only where the product permits it. Never serve a revoked malicious destination as a silent availability fallback."],
      followups: [["What if two users request the same alias?", "An atomic unique insert chooses one winner; return a conflict to the other. A preflight lookup alone races."], ["What if the mapping database fails?", "Serve only valid cached entries within the documented freshness/revocation policy; return an explicit temporary failure for uncached codes."], ["How do you support analytics?", "Emit deduplicable click events asynchronously and expose delayed aggregates with a freshness timestamp."]]
    },
    {
      id: "social-feed", title: "Design the Twitter timeline / Facebook feed and search", source: "primer",
      summary: "Separate durable posts, hybrid fanout, query indexes, and privacy-correct feed reads.",
      flow: [["Post API", "DB + transactional outbox"], ["Fanout", "Push normal, pull high-degree"], ["Timeline", "User inbox IDs + cursor"], ["Read", "Merge, rank, authorize"], ["Search", "Derived text index"]],
      feedback: "Edits/deletions update both feed caches and search indexes; serving still verifies eligibility.",
      scope: ["Support publishing posts, following accounts, reading a paginated home timeline, and keyword search over permitted posts. Clarify replies, media, ranking, private accounts, and search freshness.", "Start with chronological ordering if ranking is not required. The core software-design challenge is distribution and consistency, not inventing an ML model."],
      capacity: ["Assume 10 million posts/day and 1 billion timeline reads/day: about 116 writes/s and 11,574 reads/s before peak factors. Average fanout of 200 creates 2 billion inbox insertions/day under pure push.", "Distribution matters: one 10-million-follower author is unlike 10,000 small authors. Estimate hot-author fanout and active-follower fraction separately."],
      data: ["Use post_id, author, creation time, content/media references, audience version, deletion state, and follow edges. Timeline entries contain post IDs and sortable metadata, not copies of mutable private content.", "Keep a searchable inverted index with document/access versions. It is a read model, not the authority for post visibility. Preserve tombstones long enough for downstream cleanup/replay."],
      model: ["Use hybrid fanout: push ordinary-author IDs into follower inboxes, pull high-degree authors' recent posts at read time. Partition inboxes by user; bound retained history and rebuild from source logs when needed.", "Merge candidates with deterministic ordering, deduplicate post IDs, and use snapshot/last-sort-tuple cursors. Search combines index retrieval with access filtering and post-state checks; do not rely on eventual index deletion alone."],
      online: ["POST /posts commits metadata and outbox atomically. Workers fan out and index idempotently by post/event ID. GET /timeline?cursor=... merges inbox/pull candidates, checks access, and returns a continuation token.", "GET /search?q=... returns authorized matches with clear freshness semantics. Follow/unfollow and privacy changes propagate via events but take effect authoritatively at read time when necessary."],
      metrics: ["Track publish-to-visible/indexed delay, feed read p99, missing/duplicate posts, fanout queue age, search quality, and unauthorized/removed-post exposure.", "If a fanout worker fails halfway, replay must not duplicate inbox entries. Test celebrity spikes, follow churn, deleted posts, stale search indexes, and cursor continuation during concurrent publishing."],
      risks: ["Unbounded inboxes and hot creators cause skew; cap history, archive older data, and split hot paths. Backpressure should delay best-effort fanout, not lose authoritative posts.", "Block/private-audience changes cannot wait indefinitely for asynchronous fanout cleanup. Avoid sharing per-user feed cache entries and recheck media authorization."],
      tradeoffs: ["Push makes reads cheap but writes expensive; pull reverses that. Hybrid complexity is justified by heavy-tailed follower degree.", "Stable pagination and immediate freshness conflict. Explicit refresh boundaries and cursor expiry produce a more predictable experience than constantly reordering an active scroll."],
      followups: [["What if fanout delivery is duplicated?", "Use a unique (user_id, post_id) inbox identity or idempotent upsert with version handling."], ["How do you support a new follower?", "Backfill a bounded set of recent authorized posts and merge with future events, deduplicating overlaps."], ["Why not keep only the search index?", "It lacks the same durability, ownership, lifecycle, and access guarantees as the authoritative post store."]]
    },
    {
      id: "web-crawler", title: "Design a web crawler", source: "primer",
      summary: "Manage a durable, polite frontier and make fetch, deduplication, and indexing replayable.",
      flow: [["Seeds/frontier", "Canonical URL + priority"], ["Scheduler", "Per-host politeness + robots"], ["Fetch", "Bounded safe network worker"], ["Parse", "Content hash + extracted links"], ["Index", "Versioned documents + recrawl"]],
      feedback: "Change rates and failures update recrawl priorities; robots and network safety remain hard constraints.",
      scope: ["Clarify discovery crawl versus search indexing, allowed sites, freshness, page formats, crawl depth, and expected coverage. Respect robots directives, applicable terms, and reasonable host load.", "Define canonicalization and recrawl behavior. Fetching one page, discovering every reachable URL, and maintaining a fresh searchable corpus are different products."],
      capacity: ["Assume 100 million pages/day: about 1,157 fetches/s average. At 500 KB/page, ingress is about 50 TB/day before duplicates and compression.", "If mean fetch time is 1 second, roughly 1,157 concurrent fetches sustain that rate in a stable system before overhead. Per-host rate limits, long tails, and backpressure may dominate over raw worker count."],
      data: ["Maintain URL identity, canonical form, host, priority, next_fetch_at, robots state, status, ETag/Last-Modified, content hash, and fetched-version references.", "Use separate URL deduplication and content deduplication: different URLs may contain the same page. A probabilistic filter can accelerate checks but false positives may skip unseen URLs; use an authoritative store for important coverage guarantees."],
      model: ["Partition scheduling by host/domain to enforce politeness and avoid parallel overload. Lease frontier items with expiry/fencing; retry transient failures with bounded backoff and quarantine persistent errors.", "Fetch under strict size/time/redirect limits, parse in isolation, normalize permitted links, and enqueue new work idempotently. Use conditional requests and change-aware recrawl; preserve versions needed for debugging and freshness evaluation."],
      online: ["Internal APIs enqueue seed URLs, lease a host-eligible batch, commit a fetch result, and publish index updates with stable event IDs. A durable frontier plus object storage allows workers to be replaced.", "Restrict network egress to safe public destinations, revalidate redirects/DNS resolution, and block access to internal/metadata endpoints. Crawled HTML is untrusted data; do not execute arbitrary scripts in privileged workers."],
      metrics: ["Measure unique useful pages/day, coverage against a scoped benchmark, freshness age, fetch success by host, duplicate rate, robots/politeness violations, queue age, and cost per indexed document.", "Test infinite-calendar URL traps, redirect loops, duplicate parameters, oversized content, slow hosts, worker crashes, and repeated delivery. A high fetch count can merely mean repeatedly downloading the same pages."],
      risks: ["Unbounded discovery can exhaust storage and hammer sites. Set per-host budgets, depth/parameter policies, crawl quotas, and domain-level controls with explicit audit reasons.", "Sandbox parsers, scan unsupported content, limit decompression, and keep source URLs and provenance. Deletion or exclusion requests need propagation to indexes and retained copies under the applicable policy."],
      tradeoffs: ["Aggressive freshness increases bandwidth and host burden; prioritize high-change/high-value pages while respecting limits. Central scheduling simplifies ordering but can bottleneck; host-partitioned scheduling scales with coordination at ownership changes.", "Bloom filters reduce deduplication cost but can reduce coverage. State whether approximate discovery is acceptable, and measure false-positive effects."],
      followups: [["How do you avoid crawling the same URL twice?", "Canonical identity plus a durable dedup/lease record; tolerate redundant fetch attempts but commit results idempotently."], ["What if a page changes every second?", "Apply a bounded per-host recrawl budget and product freshness policy; do not chase every change without limits."], ["How do you restart after a crash?", "Recover the durable frontier, expire/fence old leases, replay result/index events, and verify no committed documents were lost."]]
    },
    {
      id: "distributed-cache", title: "Design a key-value store for a search engine", source: "primer",
      summary: "Define cache/store semantics, partition keys, memory policy, and node failure behavior.",
      flow: [["Client", "get/set/delete + version"], ["Router", "Shard ownership map"], ["Nodes", "Memory + eviction"], ["Replica/source", "Durability contract"], ["Rebalance", "Transfer + fencing"]],
      feedback: "Hot-key and hit-rate telemetry informs capacity; eviction must not masquerade as durable deletion.",
      scope: ["Ask whether this is an expendable search-result cache or the authoritative key-value store. Design a distributed cache first, then explain the durability additions for authoritative storage.", "Define TTL, maximum key/value sizes, consistency, eviction, and whether atomic compare-and-set is needed. Search cache keys must include normalized query, index generation, locale, and permission scope when applicable."],
      capacity: ["Assume 100 million entries at 1 KB each = about 100 GB values before keys, metadata, allocator overhead, and replication. At a 1.5x overhead and three copies, budget about 450 GB before headroom.", "At 1 million gets/s across 100 primaries, average is 10,000 gets/s/node, but hot keys and value sizes can invalidate uniform assumptions. Benchmark with the real skew and payload distribution."],
      data: ["Store key, value, expiry, version, and optional source generation. For an expendable cache, loss is a miss; for an authoritative store, add a write-ahead log, durable snapshots, and recovery verification.", "Maintain shard ownership outside ephemeral node memory. Bound TTL/size and choose eviction based on workload, such as approximate LRU/LFU; memory overhead of a perfect global LRU can be substantial."],
      model: ["Use consistent/rendezvous hashing with virtual nodes and a versioned membership map. Replicate for availability, defining whether reads may be stale and how writes are acknowledged.", "Protect the source with request coalescing, TTL jitter, bounded miss concurrency, and admission control. Hot keys can be cached on multiple serving nodes or at clients with safe freshness semantics; adding shards does not split one hot key automatically."],
      online: ["Expose GET key, SET key value ttl, DELETE key, and optional CAS expected_version. Reject oversize payloads explicitly. Bind client routing to map version and redirect stale owners safely.", "On node loss, route according to the replication/miss contract. During rebalance copy state, catch up writes, switch ownership with fencing, and retain a bounded compatibility path rather than accepting two independent primaries."],
      metrics: ["Measure hit rate, p99 latency by payload size, evictions, memory fragmentation, replica lag, source QPS, hot-key skew, and recovery/warmup time.", "Test all-nodes-cold startup, a hot-node failure, membership churn, stale routing, clock/expiry behavior, and cache stampedes. For authoritative mode, test acknowledged-write durability separately from cache availability."],
      risks: ["A stale result can cross a privacy boundary if keys omit tenant/access context. Invalidate by index/access generation and authorize returned documents.", "Avoid unlimited stale serving, memory exhaustion, and retry amplification during rebalance. Surface errors/misses distinctly so callers know whether fallback is safe."],
      tradeoffs: ["Replication improves availability but costs memory and write traffic; stronger write/read coordination increases latency. Choose by whether losing/staling a value breaks correctness or only performance.", "Caching full result pages is fast but invalidates broadly; caching candidate IDs with final authorization is more flexible and still needs freshness accounting."],
      followups: [["Does consistent hashing solve hot keys?", "It reduces remapping, not the demand on one key. Replicate or cache hot immutable reads and rethink write aggregation."], ["Would you persist every cache entry?", "Only if recovery/warmup requirements justify it; an authoritative store requires durability, while an expendable cache can often rebuild."], ["How do you stop a stampede?", "Coalesce same-key misses, limit source concurrency, jitter expirations, and use bounded stale data only where permitted."]]
    },
    {
      id: "sales-ranking", title: "Design Amazon-style sales ranking by category", source: "primer",
      summary: "Aggregate valid purchases, handle corrections, and publish reproducible category rankings.",
      flow: [["Orders", "Paid/cancel/refund event versions"], ["Normalize", "Dedup + category membership"], ["Aggregate", "Product/window counters"], ["Rank", "Per-category top-K snapshot"], ["Read API", "Version + freshness"]],
      feedback: "Refunds, category edits, and late events revise aggregates under an explicit ranking policy.",
      scope: ["Clarify units versus revenue, rolling versus lifetime rank, category hierarchy, geographic market, refresh cadence, and whether cancelled/refunded orders count.", "State that this is a hypothetical design of the published interview prompt, not a description of a company's proprietary formula. Use a simple declared score before introducing time decay."],
      capacity: ["Assume 10 million order-item events/day, about 116/s average and 2,315/s at a 20x sale peak. A product can belong to several categories, multiplying aggregate updates.", "For 100,000 categories with top 100 product IDs and 16 bytes/ID-plus-score, bare top lists occupy about 160 MB before metadata, versions, replicas, and the full counting state."],
      data: ["Use stable order_item_id, event_id, state/version, product_id, quantity/value, market, event time, category-version, and payment/refund status. Preserve source-of-truth order events for reconciliation.", "Separate exact aggregate state from materialized ranked lists. Keep snapshot IDs and watermarks so the same page/cursor does not combine ranks from different refreshes."],
      model: ["Compute net qualified units or a defined time-decayed score. Handle order state changes idempotently: a repeated refund must not subtract twice, and an older state event must not overwrite a newer one.", "For exact global per-product totals, combine all contributions before selecting category top-K. If products are disjointly partitioned after aggregation, shard top-K lists can be merged; truncated regional lists with partial totals do not generally suffice."],
      online: ["Order events flow to partitioned aggregators and periodic/streamed top-K materialization. GET /categories/{id}/ranking?market=...&snapshot=... reads a completed snapshot with deterministic tie-breaking.", "An operator can replay from an order-log offset into a new aggregate version, compare against a batch oracle, then atomically switch the read alias. Do not mutate a published snapshot halfway through an API response."],
      metrics: ["Validate aggregate counts and top-K against a batch computation under identical time/category/refund rules. Track event lag, snapshot age, rank churn, missing products, and correction delay.", "Example: 120 paid units minus 10 qualifying refunds gives 110 net units only if the stated policy counts refunds that way. A return outside the reporting window needs an explicit rule, not arbitrary subtraction."],
      risks: ["Promotions create hot products and category keys. Use partial aggregation, bounded state, and category-specific materialization schedules while preserving declared correctness.", "Monitor suspicious purchases separately from ranking policy; do not expose abuse-detection internals. Keep legitimate corrections auditable and rankings explainable at the aggregate level."],
      tradeoffs: ["Exact ranking costs more state/coordination; approximate heavy hitters can reduce cost only with measured error and a reconciliation strategy.", "More frequent refresh gives freshness but increases rank instability and cost. Publish a cadence and stable cursor rather than pretending continuously changing ranks are a static list."],
      followups: [["How do you handle refunds?", "Apply a versioned business rule and idempotent correction tied to the original order item; retain the audit history."], ["How do you break ties?", "Use a deterministic secondary key such as product ID after the declared score; preserve it within a snapshot."], ["What if category membership changes?", "Define event-time versus current taxonomy semantics, version the taxonomy, and backfill/recompute affected aggregates deliberately."]]
    },
    {
      id: "chat-system", title: "Design a WhatsApp-style messaging system", source: "chat",
      summary: "Durably accept messages, preserve conversation order, and support offline replay.",
      flow: [["Client", "Message ID + encrypted payload"], ["Gateway", "Auth + membership + connection"], ["Message service", "Durable conversation sequence"], ["Delivery", "Online socket / offline inbox"], ["Receipts", "Sent, delivered, read"]],
      feedback: "Acknowledgements advance replay cursors; reconnects deduplicate by message ID.",
      scope: ["Support one-to-one/group messaging, media references, offline delivery, and receipt semantics. Clarify group size, device count, retention, search, and whether end-to-end encryption is required.", "Do not claim privacy from encryption in transit alone. If E2EE is required, use a well-reviewed protocol/library and describe key/device lifecycle, not custom cryptography."],
      capacity: ["Assume 100 million users x 50 messages/day = 5 billion messages/day, about 57,870/s average before group fanout and peaks.", "At 1 KB encrypted payload, raw message data is about 5 TB/day before replication and delivery indexes. Ten million live connections require sharded gateways, heartbeats, and connection ownership tracking."],
      data: ["Use conversation_id, message_id, sender, per-conversation sequence, ciphertext/media reference, membership/key epoch, and server receipt time. Keep delivered/read cursors per recipient/device under the privacy contract.", "Store media in object storage; use appropriate encryption and scoped access. Presence and typing can be ephemeral and approximate; durable messages and membership need stronger state."],
      model: ["Authenticate the sender and verify current membership, deduplicate the client message ID, assign conversation ordering, durably store, then acknowledge acceptance.", "Fan out to online connections and offline queues, allowing at-least-once transport with client/server deduplication. Reconnect replays after a confirmed cursor; ordering is per conversation, not a costly universal global order."],
      online: ["POST /conversations/{id}/messages or an authenticated socket command carries a client-generated message ID. The server returns durable-acceptance status and sequence; it does not call this 'read'.", "A gateway directory maps devices to connections. Offline recipients fetch missing message ranges on reconnect. Membership changes and E2EE group key changes follow explicit epochs; removed members must not receive new messages."],
      metrics: ["Track durable acceptance availability, send-to-delivery latency, offline replay completeness, duplicate display rate, sequence gaps, receipt lag, and connection churn.", "Test gateway failure before/after durable ack, duplicate sends, group removal during send, offline devices, reordered receipt events, and long reconnect histories. Distinguish transport success from recipient delivery and reading."],
      risks: ["A hot group can overload a single sequence/fanout path; bound group size, partition delivery work, and keep conversation ordering under an explicit owner/consensus protocol.", "Limit metadata retention, defend spam with privacy-compatible controls, and provide reporting. Backups and device recovery must fit the E2EE threat model instead of silently bypassing it."],
      tradeoffs: ["Server-stored history simplifies replay but raises retention and E2EE backup questions. Per-device delivery adds state but enables correct multi-device semantics.", "Strict conversation order can add coordination latency. Presence and typing can be best-effort without weakening durable message guarantees."],
      followups: [["What if an ack is lost?", "Retry the same message ID and return the already accepted message/sequence; do not append another logical message."], ["Can the server search E2EE message text?", "Not in the ordinary plaintext-index sense without changing the threat model. Use local search or an explicitly designed, reviewed privacy-preserving approach."], ["How does offline delivery work?", "Persist encrypted messages and delivery progress, replay missing sequences on reconnect, and enforce documented retention/expiry."]]
    },
    {
      id: "file-sync", title: "Design a Dropbox-style file storage and sync system", source: "files",
      summary: "Separate bytes from metadata, version every edit, and make conflicts recoverable.",
      flow: [["Client scan", "Local version + chunk hashes"], ["Upload", "Scoped multipart/chunk storage"], ["Commit", "Manifest + version check"], ["Change log", "Per-account ordered events"], ["Sync", "Cursor + conflicts + download"]],
      feedback: "Clients acknowledge change cursors; orphaned chunks are garbage-collected only after retention and reference checks.",
      scope: ["Support upload/download, folders, sharing, and multi-device synchronization. Clarify offline edits, file size, version history, deletion recovery, and conflict UX.", "Availability can tolerate some read staleness, but ownership, ACL changes, and conflicting metadata writes need a precise correctness policy. Do not use 'eventual consistency' to justify lost edits."],
      capacity: ["Assume 1 million users uploading 100 MB/day = 100 TB/day ingress, before downloads, replication, and deduplication. Metadata throughput and byte throughput are different capacity problems.", "A 50 GB file at 100 Mbps takes about 4,000 seconds, or 66.7 minutes before overhead. Resumable chunks are essential; do not proxy the whole file through a single app-server request."],
      data: ["Keep file_id, owner/tenant, parent/name, version, chunk manifest, size/checksum, ACL version, and deletion tombstone. File identity should survive renames; paths alone are not stable identities.", "Use an ordered per-account/namespace change log and client cursors. Store immutable chunks in object storage and reference-count or trace reachability safely for cleanup; avoid leaking cross-tenant content existence through deduplication behavior."],
      model: ["Upload only missing authorized chunks, verify hashes, then atomically commit a manifest if the expected base version still matches. If it does not, preserve both edits or require a merge rather than silently overwriting.", "Notify devices of change availability, but use the durable log/cursor for correctness. Reconcile missed notifications by pulling changes; replay is idempotent using change/version IDs."],
      online: ["POST /uploads creates scoped chunk slots; POST /files/{id}/versions commits expected_version and a verified manifest. GET /changes?cursor=... yields ordered changes and continuation.", "Downloads obtain permission-checked short-lived URLs. Share/revoke operations update authoritative ACLs and invalidate access tokens/caches as required. A deleted file becomes a tombstone before retained versions/chunks are physically purged."],
      metrics: ["Measure upload completion, checksum failures, sync convergence time, conflict/lost-edit rate, metadata p99, download start latency, unauthorized accesses, and restore success.", "Test concurrent offline edits, rename+edit races, chunk loss, interrupted uploads, cursor expiry, deleted-shared files, and replay after weeks offline. Define a full-resync path when the incremental log no longer covers a cursor."],
      risks: ["Orphan cleanup can delete still-referenced chunks if reference updates race. Use transactional metadata/manifest ownership and delayed verified garbage collection.", "Protect upload endpoints, scan supported files, enforce quotas, encrypt data, and manage sharing carefully. Notification payloads should not leak private paths or file names to unauthorized devices."],
      tradeoffs: ["Content-defined chunking can improve delta reuse but adds CPU/complexity; fixed chunks are simpler. Deduplication saves storage but must not compromise tenant isolation or encryption.", "Strong metadata conflict detection preserves edits but requires an understandable conflict UX. A last-writer-wins default is simple and can silently lose user work."],
      followups: [["Two laptops edit offline. Who wins?", "Neither automatically unless the product explicitly chooses that policy; detect the shared base version and preserve conflict copies or perform a supported merge."], ["Are push notifications enough for sync?", "No. They can be lost; the durable change log and cursor are the source of synchronization truth."], ["How do you delete safely?", "Write a tombstone, propagate access changes, retain recovery history per policy, then garbage-collect unreferenced bytes with verified reachability."]]
    },
    {
      id: "ride-matching", title: "Design an Uber-style ride matching system", source: "rides",
      summary: "Use fresh geographic candidates but transactional assignment of scarce drivers.",
      flow: [["Driver updates", "Location + sequence + heartbeat"], ["Geo search", "Nearby available candidates"], ["Dispatch", "ETA shortlist + offer lease"], ["Assignment", "Atomic driver/trip state"], ["Trip events", "State machine + notification"]],
      feedback: "Accept/reject, pickup, cancellations, and stale location events refine matching and freshness policy.",
      scope: ["Support fare estimate, ride request, nearby driver matching, acceptance, and core trip status. Clarify region, offer timeout, ride categories, and whether routing/pricing are internal or dependencies.", "The crucial invariant is no driver assigned to overlapping active trips, not merely a fast nearest-neighbor query. Location freshness is approximate; assignment ownership must be authoritative."],
      capacity: ["Assume 1 million active drivers sending updates every 5 seconds: 200,000 location updates/s. At 100 bytes/update that is 20 MB/s before protocol, indexing, and replication overhead.", "Ride requests may be far less frequent but concentrated during events. Size hot geographic cells separately from global averages and bound search expansion/offer fanout."],
      data: ["Store driver availability/state/version, location with timestamp/sequence, active trip, rider request with idempotency key, offer lease/expiry, and trip event log.", "Keep location in a spatial read model with TTL; keep assignment state in a transactional/conditional-write authority. Old out-of-order location updates must not overwrite a newer position."],
      model: ["Retrieve nearby available candidates using geo cells, compute ETA for a shortlist, and score feasible matches. A simple nearest-ETA baseline is adequate before sophisticated marketplace optimization.", "Offer sequentially or in a carefully controlled small batch. Acceptance atomically changes the driver from available/offered to assigned for the same valid lease and updates trip state under an invariant-preserving protocol. Expired offers cannot be revived by delayed messages."],
      online: ["POST /rides with an idempotency key creates one request. Dispatch workers claim a durable request, propose candidates, and send versioned expiring offers. POST /offers/{id}/accept validates lease, driver state, and trip state.", "Location streaming and rider notifications are asynchronous. Reconcile client displays with authoritative trip status; a notification that was delivered is not proof an assignment committed."],
      metrics: ["Measure match success/time, pickup ETA error, driver utilization, cancellation, stale-location rate, double-assignment incidents, and fairness across areas.", "Test simultaneous acceptances, duplicated ride requests, worker crash after assignment but before notification, old offer acceptance, driver disconnect, and large local demand spikes. Replay the state machine under reordered events."],
      risks: ["Stale geo indexes produce unavailable candidates; recheck driver state before offering/assigning. Bound leases and fence old dispatch workers so retries cannot reserve the same driver twice.", "Protect precise location, minimize retention, authorize trip/location access, and provide safety escalation. Do not reveal private driver/rider positions outside the active authorized workflow."],
      tradeoffs: ["Strong assignment coordination adds latency but prevents an invalid double booking. Geographic retrieval can be approximate and eventually updated while assignment cannot.", "Wider searches and parallel offers improve match speed but can waste driver attention and create race complexity. Use controlled offers with leases and measure marketplace side effects."],
      followups: [["Two riders select the same driver. What happens?", "A conditional state transition or transactional reservation allows one assignment; the other request retries other eligible candidates."], ["Why not assign directly from the geo cache?", "The cache may be stale and does not protect the driver/trip invariant under concurrent requests."], ["What if the accept response is lost?", "Retry by offer/operation ID and return the committed result; do not create a second trip."]]
    }
  ];

  const sources = {
    primer: ["System Design Primer: published questions and sample discussions", "https://github.com/donnemartin/system-design-primer#system-design-interview-questions-with-solutions"],
    bitly: ["Hello Interview: Design Bit.ly", "https://www.hellointerview.com/learn/system-design/problem-breakdowns/bitly"],
    chat: ["Hello Interview: Design WhatsApp", "https://www.hellointerview.com/learn/system-design/problem-breakdowns/whatsapp"],
    files: ["Hello Interview: Design Dropbox", "https://www.hellointerview.com/learn/system-design/problem-breakdowns/dropbox"],
    rides: ["Hello Interview: Design Uber", "https://www.hellointerview.com/learn/system-design/problem-breakdowns/uber"]
  };

  const tracks = { ml: ["ML worked answers", ml], software: ["Software interview questions", software], concepts: ["Software concepts", concepts] };
  const fields = [
    ["scope", "01 / Clarify the requirements"],
    ["capacity", "02 / Estimate capacity and latency"],
    ["data", "03 / Data, labels, and storage"],
    ["model", "04 / Baseline, algorithm, and consistency"],
    ["online", "05 / APIs and end-to-end execution"],
    ["metrics", "06 / Evaluation and success metrics"],
    ["risks", "07 / Failures, privacy, and safety"],
    ["tradeoffs", "08 / Trade-offs and rollout"]
  ];
  const rubric = ["I clarified the goal and correctness constraints.", "I estimated load with units and stated assumptions.", "I traced the full data/API path and chose a baseline.", "I defined metrics with denominators and relevant slices.", "I handled failures, privacy, trade-offs, and follow-ups."];
  const escape = value => String(value).replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
  const paragraphs = items => items.map(text => `<p>${escape(text)}</p>`).join("");
  function diagram(item) {
    return `<figure class="concept-diagram sd-diagram"><figcaption>${escape(item.title)}: architecture / reasoning map</figcaption><div class="cd-flow">${item.flow.map(([name, text], i) => `${i ? '<span class="cd-arrow" aria-hidden="true">&rarr;</span>' : ""}<div class="cd-card cd-color-${i % 6}"><strong>${escape(name)}</strong><p>${escape(text)}</p></div>`).join("")}</div>${item.feedback ? `<p class="cd-caption"><strong>Feedback / control path:</strong> ${escape(item.feedback)}</p>` : ""}</figure>`;
  }
  function disclosure(title, body, open = false) {
    return `<details class="chapter-details sd-answer"${open ? " open" : ""}><summary>${escape(title)}</summary><div class="chapter-detail-body">${body}</div></details>`;
  }
  function validRoute(track, id) {
    if (track === undefined) return id === undefined;
    return Object.hasOwn(tracks, track) && (id === undefined || tracks[track][1].some(item => item.id === id));
  }
  function navigation(track) {
    return `<nav class="sd-tabs" aria-label="System design sections"><a class="button secondary small-button" href="#design"${track === undefined ? ' aria-current="page"' : ""}>All topics</a>${Object.entries(tracks).map(([key, [title, items]]) => `<a class="button secondary small-button" href="#design/${key}"${track === key ? ' aria-current="page"' : ""}>${escape(title)} (${items.length})</a>`).join("")}</nav>`;
  }
  function sourceMarkup(key) {
    const [label, url] = sources[key];
    return `<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)} &nearr;</a>`;
  }
  function provenance(track, item) {
    return track === "ml"
      ? "User-supplied interview prompt. Original worked answer; synthetic load assumptions, not a company's actual specifications."
      : `Published interview-practice prompt, verified against ${escape(sources[item.source][0])}. This is not an authenticated company interview transcript; the answer and numerical assumptions here are original.`;
  }
  function indexPage(root, track) {
    root.innerHTML = `<section id="design-library" class="sd-library"><header class="page-heading"><div><span class="eyebrow">SYSTEM DESIGN / WORKED ANSWERS</span><h1>Design it. Defend the decisions.</h1><p class="intro">${ml.length} ML designs, ${concepts.length} software concepts, and ${software.length} sourced interview-practice questions. Architecture first; detailed answers when you want them.</p></div></header>${navigation(track)}<div class="viz-explanation"><strong>Interview provenance:</strong> ML prompts are your requested questions. Software prompts are published in System Design Primer and Hello Interview, not claimed as verified questions asked by a specific employer. All explanations, answers, and numbers here are original teaching examples.</div><section class="panel"><h2>A 45-minute answer plan</h2><div class="cd-tokens"><span class="cd-token">0-5 min: scope</span><span class="cd-token">5-10: scale + data</span><span class="cd-token">10-25: architecture</span><span class="cd-token">25-35: deep dive</span><span class="cd-token">35-45: metrics + failures</span></div><p>Lead with requirements and a simple baseline. Trace one request, explain one hard invariant, quantify a bottleneck, and defend what you deliberately left out.</p></section><label class="sd-search-label" for="design-search">Search questions, concepts, and full answers</label><input id="design-search" class="sd-search" type="search" placeholder="Try: fraud, watermark, consistency, translation..." autocomplete="off"><p id="design-results-status" class="muted" role="status"></p><div id="design-results"></div><section class="sources"><h2>Verified public practice sources</h2>${Object.keys(sources).map(sourceMarkup).join("")}<p>These pages establish the published question/topic, not a universal hiring loop. Study their alternative approaches alongside these original answers.</p></section></section>`;
    const container = root.querySelector("#design-library");
    const search = container.querySelector("#design-search");
    const update = () => {
      const query = search.value.trim().toLowerCase();
      let total = 0;
      container.querySelector("#design-results").innerHTML = Object.entries(tracks).filter(([key]) => track === undefined || key === track).map(([key, [title, items]]) => {
        const selected = items.filter(item => JSON.stringify(item).toLowerCase().includes(query));
        total += selected.length;
        return selected.length ? `<section class="sd-result-group"><h2>${escape(title)}</h2><div class="chapter-grid">${selected.map((item, index) => `<a class="panel sd-topic-card" href="#design/${key}/${item.id}"><span class="eyebrow">${key === "concepts" ? "CONCEPT + Q&A" : key === "ml" ? "ML WORKED ANSWER" : "SOURCED PRACTICE PROMPT"} / ${String(index + 1).padStart(2, "0")}</span><h3>${escape(item.title)}</h3><p>${escape(item.summary)}</p><span class="sd-card-link">Open diagram and detailed answer &rarr;</span></a>`).join("")}</div></section>` : "";
      }).join("");
      container.querySelector("#design-results-status").textContent = `${total} matching topic${total === 1 ? "" : "s"}`;
      if (!total) container.querySelector("#design-results").innerHTML = '<div class="empty-state"><h2>No matching designs.</h2><p>Try a broader term or select All topics.</p></div>';
    };
    search.addEventListener("input", update);
    update();
  }
  function detailPage(root, track, item) {
    const concept = track === "concepts";
    const answer = concept
      ? disclosure("Explain the concept simply", paragraphs([item.explanation]), true)
        + disclosure("Work through the example", paragraphs([item.example]))
        + disclosure("Interview question: " + item.question, paragraphs([item.answer]))
        + disclosure("Common trap", paragraphs([item.trap]))
      : fields.map(([key, title], i) => disclosure(track === "software" && key === "data" ? "03 / Data model and storage" : title, paragraphs(item[key]), i === 0)).join("")
        + disclosure("09 / Interviewer follow-ups and strong answers", item.followups.map(([question, answer]) => `<h3>${escape(question)}</h3><p>${escape(answer)}</p>`).join(""));
    const items = tracks[track][1], position = items.indexOf(item);
    root.innerHTML = `<article id="design-detail" class="sd-detail"><header class="lesson-header"><span class="eyebrow">SYSTEM DESIGN / ${concept ? "CONCEPT + INTERVIEW Q&A" : track === "ml" ? "ML WORKED ANSWER" : "SOFTWARE WORKED ANSWER"}</span><h1>${escape(item.title)}</h1><p class="intro">${escape(item.summary)}</p></header>${navigation(track)}<p class="sd-provenance">${concept ? "Original concept explanation and interview-style drill. See the public practice sources in the library for broader preparation." : provenance(track, item)}</p><div class="sd-toolbar"><button type="button" class="button" data-design-action="practice">Try without the answer</button><a class="button secondary" href="#design/${track}">Browse this section</a></div><section id="design-practice" class="panel" hidden><h2>Your whiteboard / answer scratchpad</h2><p>Try the 45-minute structure: requirements, scale, data, architecture, deep dive, evaluation, and failures. This scratchpad is temporary: it clears when you leave this page and is never uploaded.</p><label for="design-draft">Your design and trade-offs</label><textarea id="design-draft" class="sd-draft" rows="12" placeholder="State assumptions. Draw the data path. Explain the hardest trade-off."></textarea><button type="button" class="button secondary" data-design-action="reveal">Reveal the worked answer</button></section><div id="design-solution">${diagram(item)}<div class="chapter-reading-controls"><strong>Detailed answer, not a memorized script.</strong><p>Start with the map. Open individual sections or the complete answer; adapt assumptions to the interviewer.</p><button type="button" class="button secondary small-button" data-design-action="open">Show complete answer</button> <button type="button" class="button text small-button" data-design-action="close">Fold explanations</button></div>${answer}${concept ? "" : `<section class="sources"><h2>Prompt provenance</h2><p>${provenance(track, item)}</p>${track === "software" ? sourceMarkup(item.source) : '<a href="#design">Back to all original ML answers</a>'}</section>`}</div><section class="panel sd-self-check"><h2>Defend your design</h2><p>Use this after attempting an answer. This is self-review, not an automatic correctness grade.</p>${rubric.map((text, i) => `<label class="sd-rubric"><input type="checkbox" data-design-rubric="${i}"><span>${escape(text)}</span></label>`).join("")}<p id="design-self-score" role="status">Self-check: 0 / 5 covered.</p></section><nav class="sd-toolbar" aria-label="More system design topics">${position > 0 ? `<a class="button secondary" href="#design/${track}/${items[position - 1].id}">&larr; Previous topic</a>` : ""}${position + 1 < items.length ? `<a class="button secondary" href="#design/${track}/${items[position + 1].id}">Next topic &rarr;</a>` : ""}</nav></article>`;
    const container = root.querySelector("#design-detail");
    let practicing = false;
    container.addEventListener("click", event => {
      const button = event.target.closest("[data-design-action]");
      if (!button) return;
      const action = button.dataset.designAction;
      if (action === "open" || action === "close") container.querySelectorAll(".sd-answer").forEach(details => { details.open = action === "open"; });
      else if (action === "practice") {
        practicing = !practicing;
        container.querySelector("#design-practice").hidden = !practicing;
        container.querySelector("#design-solution").hidden = practicing;
        button.textContent = practicing ? "Return to study view" : "Try without the answer";
        if (practicing) container.querySelector("#design-draft").focus();
      } else if (action === "reveal") container.querySelector("#design-solution").hidden = false;
    });
    container.addEventListener("change", event => {
      if (event.target.matches("[data-design-rubric]")) container.querySelector("#design-self-score").textContent = `Self-check: ${container.querySelectorAll("[data-design-rubric]:checked").length} / 5 covered. Self-reported, not a correctness grade.`;
    });
  }
  function mount(root, track, id) {
    if (!validRoute(track, id)) throw new RangeError("Unknown system design route.");
    if (id === undefined) indexPage(root, track);
    else detailPage(root, track, tracks[track][1].find(item => item.id === id));
  }
  function validate() {
    for (const [track, [, items]] of Object.entries(tracks)) {
      const ids = new Set();
      for (const item of items) {
        if (!/^[a-z0-9-]+$/.test(item.id) || ids.has(item.id)) throw new RangeError(`Invalid or duplicate design ID: ${track}/${item.id}`);
        ids.add(item.id);
        if (!item.title || !item.summary || item.flow.length < 3 || item.flow.some(step => step.length !== 2 || step.some(value => !value))) throw new RangeError(`Incomplete design map: ${item.id}`);
        if (track === "concepts") {
          if (["explanation", "example", "question", "answer", "trap"].some(key => !item[key])) throw new RangeError(`Incomplete concept: ${item.id}`);
        } else {
          if (fields.some(([key]) => !Array.isArray(item[key]) || item[key].length < 2 || item[key].some(value => !value))) throw new RangeError(`Incomplete design answer: ${item.id}`);
          if (item.followups.length !== 3 || item.followups.some(pair => pair.length !== 2 || pair.some(value => !value))) throw new RangeError(`Incomplete follow-ups: ${item.id}`);
          if (track === "software" && !Object.hasOwn(sources, item.source)) throw new RangeError(`Unknown design source: ${item.id}`);
        }
      }
    }
    if (ml.length !== 15 || software.length !== 8 || concepts.length !== 17) throw new RangeError("System design coverage changed; review the requested topic counts.");
  }
  validate();
  return { ml, concepts, software, sources, validRoute, mount };
})();
